    /// Stage 4d Manual-redirect CopyArea clip-by-children fix.
    ///
    /// Scenario from `yserver-hw-mate.log` (CC frame + reparented
    /// CC client window in one redirected backing):
    ///   - Frame W=997, H=652 at parent-local (0, 0).
    ///   - Reparented CC client at (11, 41) inside the frame,
    ///     size 975×600 (mapped).
    ///   - Marco copies its decoration pixmap into the frame with
    ///     a `ClipByChildren` GC, full 997×652.
    ///
    /// Pre-fix: v2's `copy_area` blits the full 997×652 into the
    /// redirected backing, clobbering CC's content. Visible symptom:
    /// only the small region CC repaints next survives — the famous
    /// "top-left square only" artefact.
    ///
    /// Spec-correct behaviour (Xorg `mi/midispcur.c` + the
    /// `ClipByChildren` rule): subtract every mapped child window's
    /// rect from the destination rect before issuing the copy. For
    /// this one-child case the result is exactly four strips: top,
    /// bottom, left-of-child, right-of-child.
    #[test]
    fn copy_area_clip_by_children_excludes_mapped_child_rect() {
        use ash::vk;
        let dst = vk::Rect2D {
            offset: vk::Offset2D { x: 0, y: 0 },
            extent: vk::Extent2D {
                width: 997,
                height: 652,
            },
        };
        let child = vk::Rect2D {
            offset: vk::Offset2D { x: 11, y: 41 },
            extent: vk::Extent2D {
                width: 975,
                height: 600,
            },
        };

        let got = compute_copy_area_dst_rects(dst, &[child]);

        // Expected order: top strip, bottom strip, left middle,
        // right middle (Xorg/pixman band order).
        let want = [
            vk::Rect2D {
                offset: vk::Offset2D { x: 0, y: 0 },
                extent: vk::Extent2D {
                    width: 997,
                    height: 41,
                },
            },
            vk::Rect2D {
                offset: vk::Offset2D { x: 0, y: 641 },
                extent: vk::Extent2D {
                    width: 997,
                    height: 11,
                },
            },
            vk::Rect2D {
                offset: vk::Offset2D { x: 0, y: 41 },
                extent: vk::Extent2D {
                    width: 11,
                    height: 600,
                },
            },
            vk::Rect2D {
                offset: vk::Offset2D { x: 986, y: 41 },
                extent: vk::Extent2D {
                    width: 11,
                    height: 600,
                },
            },
        ];

        assert_eq!(
            got.len(),
            want.len(),
            "expected 4 surviving strips (top, bottom, left-middle, right-middle); \
             pre-fix returns the unclipped 1-rect input, which is the bug",
        );
        for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
            assert_eq!(
                (g.offset.x, g.offset.y, g.extent.width, g.extent.height),
                (w.offset.x, w.offset.y, w.extent.width, w.extent.height),
                "strip {i} mismatch",
            );
        }
    }

    #[test]
    fn copy_area_clip_by_children_no_children_returns_input() {
        use ash::vk;
        let dst = vk::Rect2D {
            offset: vk::Offset2D { x: 5, y: 7 },
            extent: vk::Extent2D {
                width: 100,
                height: 80,
            },
        };
        let got = compute_copy_area_dst_rects(dst, &[]);
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].offset.x, 5);
        assert_eq!(got[0].offset.y, 7);
        assert_eq!(got[0].extent.width, 100);
        assert_eq!(got[0].extent.height, 80);
    }

    // ── compute_render_composite_clip — audit #2 (2026-05-19) ────────
    //
    // Mirrors Xorg's `miComputeCompositeRegion`
    // (`render/mipict.c:316-389`). Per-test vectors hand-traced from
    // the Xorg algorithm so the expected output is grounded in the
    // reference, not in my own arithmetic (per
    // `feedback_test_vectors_must_be_external`).

    /// All three clips `None` → result `None` (engine paints
    /// everywhere, matching Xorg's "no clientClip" path which
    /// leaves pRegion unconstrained beyond dst extent).
    #[test]
    fn compute_render_composite_clip_all_none_returns_none() {
        let got = compute_render_composite_clip(None, None, (0, 0), None, (0, 0));
        assert!(got.is_none());
    }

    /// Only dst clip set → result is dst clip (no translation).
    #[test]
    fn compute_render_composite_clip_only_dst() {
        let dst = vec![Rectangle16 {
            x: 10,
            y: 20,
            width: 30,
            height: 40,
        }];
        let got = compute_render_composite_clip(Some(&dst), None, (0, 0), None, (0, 0));
        assert_eq!(got.as_deref(), Some(dst.as_slice()));
    }

    /// Only src clip set, src and dst coincide (xDst==xSrc, yDst==
    /// ySrc → translation (0,0)) → result is src clip as-is. This
    /// is the load-bearing case for the audit: xfwm4/muffin set a
    /// clip on a source picture and pre-fix yserver ignored it.
    #[test]
    fn compute_render_composite_clip_src_only_zero_translation() {
        let src = vec![Rectangle16 {
            x: 5,
            y: 5,
            width: 10,
            height: 10,
        }];
        let got = compute_render_composite_clip(None, Some(&src), (0, 0), None, (0, 0));
        assert_eq!(got.as_deref(), Some(src.as_slice()));
    }

    /// Src clip translates to dst space by (xDst - xSrc, yDst -
    /// ySrc). Per Xorg `mipict.c:356`:
    /// `miClipPictureSrc(pRegion, pSrc, xDst - xSrc, yDst - ySrc)`.
    /// Set src clip {0,0 4×4}, composite from src(2,2) to
    /// dst(10,20), 4×4 — translation is (10-2, 20-2) = (8, 18).
    /// Expected: src clip translated to {8,18 4×4}.
    #[test]
    fn compute_render_composite_clip_translates_src_clip_to_dst_space() {
        let src = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 4,
            height: 4,
        }];
        let got = compute_render_composite_clip(None, Some(&src), (8, 18), None, (0, 0));
        assert_eq!(
            got.as_deref(),
            Some(
                &[Rectangle16 {
                    x: 8,
                    y: 18,
                    width: 4,
                    height: 4,
                }][..]
            )
        );
    }

    /// Dst clip ∩ src-translated clip when the two overlap on a
    /// strict sub-rect. dst clip {0,0 100×100}; src clip {0,0 50×50}
    /// translated by (20, 30) → {20,30 50×50}. Intersection:
    /// {20,30 50×50} (src translates fully inside dst).
    #[test]
    fn compute_render_composite_clip_dst_and_src_intersection() {
        let dst = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 100,
            height: 100,
        }];
        let src = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 50,
            height: 50,
        }];
        let got = compute_render_composite_clip(Some(&dst), Some(&src), (20, 30), None, (0, 0));
        assert_eq!(
            got.as_deref(),
            Some(
                &[Rectangle16 {
                    x: 20,
                    y: 30,
                    width: 50,
                    height: 50,
                }][..]
            )
        );
    }

    /// Disjoint dst and src-translated clips → empty result (which
    /// Xorg treats as "paint nothing" — `miComputeCompositeRegion`
    /// returns FALSE there).
    #[test]
    fn compute_render_composite_clip_disjoint_yields_empty() {
        let dst = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 10,
            height: 10,
        }];
        let src = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 10,
            height: 10,
        }];
        // Translate src by (100, 0) → {100,0 10×10}; disjoint from
        // dst {0,0 10×10}.
        let got = compute_render_composite_clip(Some(&dst), Some(&src), (100, 0), None, (0, 0));
        assert_eq!(got.as_deref(), Some(&[][..]));
    }

    /// Three-way intersection: dst ∩ src ∩ mask. Use disjoint
    /// translations that all overlap at one corner. dst {0,0 50×50},
    /// src {0,0 50×50} translated by (10, 10) → {10,10 50×50},
    /// mask {0,0 50×50} translated by (20, 20) → {20,20 50×50}.
    /// Three-way intersection: {20,20 30×30}.
    #[test]
    fn compute_render_composite_clip_three_way_intersection() {
        let dst = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 50,
            height: 50,
        }];
        let src = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 50,
            height: 50,
        }];
        let mask = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 50,
            height: 50,
        }];
        let got =
            compute_render_composite_clip(Some(&dst), Some(&src), (10, 10), Some(&mask), (20, 20));
        assert_eq!(
            got.as_deref(),
            Some(
                &[Rectangle16 {
                    x: 20,
                    y: 20,
                    width: 30,
                    height: 30,
                }][..]
            )
        );
    }

    /// Multi-rect dst clip ∩ single src clip translated: every
    /// dst rect intersects with the translated src rect; union of
    /// intersections is what the engine should emit per-scissor.
    #[test]
    fn compute_render_composite_clip_multi_rect_dst_with_single_src() {
        let dst = vec![
            Rectangle16 {
                x: 0,
                y: 0,
                width: 10,
                height: 10,
            },
            Rectangle16 {
                x: 20,
                y: 0,
                width: 10,
                height: 10,
            },
        ];
        // Src clip {0,0 100×100} translated by (0, 0) → covers
        // both dst rects. Result: both dst rects survive.
        let src = vec![Rectangle16 {
            x: 0,
            y: 0,
            width: 100,
            height: 100,
        }];
        let got = compute_render_composite_clip(Some(&dst), Some(&src), (0, 0), None, (0, 0));
        assert_eq!(got.as_deref(), Some(dst.as_slice()));
    }

    /// GC clip intersection: rect partially inside a single clip rect
    /// produces the intersection alone. Pre-fix the stub returns the
    /// whole rect — losing the GC clip semantics.
    #[test]
    fn intersect_rect_with_clip_single_overlapping_clip_returns_intersection() {
        use ash::vk;
        let rect = vk::Rect2D {
            offset: vk::Offset2D { x: 0, y: 0 },
            extent: vk::Extent2D {
                width: 200,
                height: 200,
            },
        };
        let clip = vec![vk::Rect2D {
            offset: vk::Offset2D { x: 50, y: 50 },
            extent: vk::Extent2D {
                width: 100,
                height: 100,
            },
        }];
        let got = intersect_rect_with_clip(rect, &clip);
        assert_eq!(got.len(), 1, "single clip ∩ rect = one intersection");
        assert_eq!(
            (
                got[0].offset.x,
                got[0].offset.y,
                got[0].extent.width,
                got[0].extent.height,
            ),
            (50, 50, 100, 100),
        );
    }

    #[test]
    fn intersect_rect_with_clip_empty_clip_returns_empty() {
        use ash::vk;
        // Empty clip-rect list represents an empty XFixes region — paint nothing.
        let rect = vk::Rect2D {
            offset: vk::Offset2D { x: 0, y: 0 },
            extent: vk::Extent2D {
                width: 10,
                height: 10,
            },
        };
        let got = intersect_rect_with_clip(rect, &[]);
        assert!(got.is_empty());
    }

    /// Multi-rect clip: dst that straddles two non-contiguous clip rects
    /// produces two intersections.
    #[test]
    fn intersect_rect_with_clip_multi_rect_clip_produces_per_rect_intersections() {
        use ash::vk;
        let rect = vk::Rect2D {
            offset: vk::Offset2D { x: 0, y: 0 },
            extent: vk::Extent2D {
                width: 200,
                height: 100,
            },
        };
        let clip = vec![
            vk::Rect2D {
                offset: vk::Offset2D { x: 10, y: 10 },
                extent: vk::Extent2D {
                    width: 40,
                    height: 40,
                },
            },
            vk::Rect2D {
                offset: vk::Offset2D { x: 150, y: 10 },
                extent: vk::Extent2D {
                    width: 40,
                    height: 40,
                },
            },
        ];
        let got = intersect_rect_with_clip(rect, &clip);
        assert_eq!(got.len(), 2);
        assert_eq!(
            (
                got[0].offset.x,
                got[0].offset.y,
                got[0].extent.width,
                got[0].extent.height,
            ),
            (10, 10, 40, 40),
        );
        assert_eq!(
            (
                got[1].offset.x,
                got[1].offset.y,
                got[1].extent.width,
                got[1].extent.height,
            ),
            (150, 10, 40, 40),
        );
    }

    #[test]
    fn copy_area_clip_by_children_disjoint_child_returns_input() {
        // Child fully outside dst → no clipping.
        use ash::vk;
        let dst = vk::Rect2D {
            offset: vk::Offset2D { x: 0, y: 0 },
            extent: vk::Extent2D {
                width: 50,
                height: 50,
            },
        };
        let child = vk::Rect2D {
            offset: vk::Offset2D { x: 200, y: 200 },
            extent: vk::Extent2D {
                width: 10,
                height: 10,
            },
        };
        let got = compute_copy_area_dst_rects(dst, &[child]);
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].offset.x, 0);
        assert_eq!(got[0].offset.y, 0);
    }

    // ────────────────────────────────────────────────────────────
    // Phase 2 root-cause pin (Task 7.5).
    //
    // The yserver-core sibling tests
    // (`reparent_*_redirect_*` in
    // `crates/yserver-core/src/core_loop/process_request.rs`) pin
    // the backing-existence state on the resource layer. This test
    // exercises the actual user-visible path: drive a
    // `ReparentWindow` through the full `process_request`
    // dispatcher, then assert
    // `resolve_paint_target(nm_applet_host_xid)` routes through
    // mate-panel's redirected ancestor with the correct
    // screen-coord offset — the symptom that breaks the live
    // mate-panel tray.
    // ────────────────────────────────────────────────────────────

    // ── DRIFT 1 regression test: input-shape empty-vs-absent (backend) ──
    //
    // Companion to the core-side regression tests in
    // crates/yserver-core/src/server.rs. GREEN as of Step 1a (findings
    // 2026-06-18): set_shape_rectangles now carries an Option so an
    // explicit empty region `Some([])` is stored faithfully (not deleted),
    // and cursor_inside_shape reads `Some([])` as click-through — matching
    // core. Before Step 1a the API collapsed `None` and `Some([])` to an
    // empty slice and deleted the entry, so this returned `above` (opaque).
    #[test]
    fn drift1_backend_empty_input_shape_is_click_through() {
        let mut b = KmsBackend::for_tests();

        // `below` (0x1000, opaque) under `above` (0x2000, topmost); full
        // overlap; cursor in the overlap.
        for (xid, rank) in [(0x1000_u32, 0_u64), (0x2000_u32, 1_u64)] {
            b.windows.insert(
                xid,
                super::WindowGeometry {
                    x: 0,
                    y: 0,
                    width: 200,
                    height: 200,
                    depth: 32,
                    mapped: true,
                    parent: None,
                    stack_rank: rank,
                    bg_pixel: None,
                    bg_pixmap: None,
                    cursor: None,
                },
            );
        }
        b.core.top_level_order.push(0x1000); // below
        b.core.top_level_order.push(0x2000); // above (topmost)
        b.core.cursor_x = 50.0;
        b.core.cursor_y = 50.0;

        // `above` is given an explicit EMPTY input region — Some(&[]),
        // NOT None (which would mean "unset" → opaque). This is the same
        // client-facing path a compositor uses for a click-through window.
        b.set_shape_rectangles(None, 0x2000, 2 /* input */, Some(&[]))
            .expect("set explicit empty input shape");

        // The empty input region lets the click fall through to `below`.
        assert_eq!(
            b.window_under_cursor(),
            Some(0x1000),
            "empty input shape must be click-through at the backend hit-test, \
             matching core_empty_input_shape_makes_window_click_through"
        );
    }

    // ── DRIFT 2 regression: top-level order projects core children ──
    //
    // GREEN as of Step 2 (findings 2026-06-18 §8): the backend's top-level
    // z-order is a pure projection of core children via
    // `sync_top_level_order`, so it inherits core's conditional TopIf
    // occlusion for free. A TopIf that core treats as a no-op (no
    // overlapping higher sibling) leaves the projected order unchanged —
    // whereas the deleted independent `restack_top_level` raised
    // unconditionally and drifted.
    #[test]
    fn drift2_topif_noop_keeps_backend_order_in_sync_with_core() {
        use yserver_core::resources::ROOT_WINDOW;
        use yserver_protocol::x11::{ConfigureWindowRequest, ResourceId};

        let mut state = ServerState::new();
        let mut b = KmsBackend::for_tests();

        // Three NON-overlapping top-levels A<mid<C (A bottom, C top).
        let a = ResourceId(0x0010_0200);
        let mid = ResourceId(0x0010_0300);
        let c = ResourceId(0x0010_0400);
        seed_state_window(&mut state, &mut b, a, ROOT_WINDOW, 0, 0, 100, 100);
        seed_state_window(&mut state, &mut b, mid, ROOT_WINDOW, 200, 0, 100, 100);
        seed_state_window(&mut state, &mut b, c, ROOT_WINDOW, 400, 0, 100, 100);
        for w in [a, mid, c] {
            let _ = state.resources.map_window(w);
        }
        // Seed a deliberately WRONG backend order to prove the sync derives
        // from core children, not from prior backend state.
        b.core.top_level_order = vec![synth_host_xid(c), synth_host_xid(a)];

        // Client sends TopIf (stack_mode=2) on A with no sibling. CORE: A
        // has no overlapping higher sibling → no-op; children stays [A,mid,C].
        state.resources.configure_window(ConfigureWindowRequest {
            window: a,
            value_mask: 0,
            x: None,
            y: None,
            width: None,
            height: None,
            border_width: None,
            sibling: None,
            stack_mode: Some(2),
        });
        // Production calls this from the ConfigureWindow handler after
        // configure_window.
        b.sync_top_level_order(&state);

        let expected: Vec<u32> = state
            .resources
            .children(ROOT_WINDOW)
            .iter()
            .map(|id| synth_host_xid(*id))
            .collect();
        assert_eq!(
            b.core.top_level_order, expected,
            "top_level_order must project core children order"
        );
        assert_eq!(
            b.core.top_level_order,
            vec![synth_host_xid(a), synth_host_xid(mid), synth_host_xid(c)],
            "a no-op TopIf leaves the projected order [A, mid, C]"
        );
    }

    // ── DRIFT 2b regression: COW stays topmost across a raise ──
    //
    // GREEN as of Step 2: `top_level_order` projects core children, and
    // core caps a raise just below the COW (`cow_aware_top_index`), so the
    // projection keeps the COW last. The deleted `restack_top_level`
    // pushed a raised window ABOVE the COW, breaking always-on-top.
    #[test]
    fn drift2_raise_keeps_cow_on_top() {
        use yserver_core::resources::{COMPOSITE_OVERLAY_WINDOW, ROOT_WINDOW};
        use yserver_protocol::x11::{ConfigureWindowRequest, ResourceId};

        let mut state = ServerState::new();
        let mut b = KmsBackend::for_tests();

        // A normal top-level, then materialize the COW on top of it.
        let win = ResourceId(0x0010_0800);
        seed_state_window(&mut state, &mut b, win, ROOT_WINDOW, 0, 0, 100, 100);
        let _ = state.resources.map_window(win);
        state.resources.materialize_cow_resource(
            yserver_core::backend::WindowHandle::from_raw_panicking(COMPOSITE_OVERLAY_WINDOW.0),
        );

        // Client/WM raises `win` to the top. CORE caps it just below the COW.
        state.resources.configure_window(ConfigureWindowRequest {
            window: win,
            value_mask: 0,
            x: None,
            y: None,
            width: None,
            height: None,
            border_width: None,
            sibling: None,
            stack_mode: Some(0), // Above, no sibling → raise to top
        });
        b.sync_top_level_order(&state);

        assert_eq!(
            b.core.top_level_order.last(),
            Some(&COMPOSITE_OVERLAY_WINDOW.0),
            "the Composite Overlay Window must stay topmost after a raise-to-top"
        );
        assert!(
            b.core.top_level_order.contains(&synth_host_xid(win)),
            "the raised window is still present (just below the COW)"
        );
    }

    // ── DRIFT 2 projection shape: unmapped included, subwindows excluded ──
    //
    // Codex review 2026-06-18: `sync_top_level_order` must include unmapped
    // root children (X11 stacking order survives unmap/remap) and exclude
    // subwindows (reached via descendant recursion, not the top-level walk).
    #[test]
    fn sync_top_level_order_includes_unmapped_excludes_subwindows() {
        use yserver_core::resources::ROOT_WINDOW;
        use yserver_protocol::x11::ResourceId;

        let mut state = ServerState::new();
        let mut b = KmsBackend::for_tests();

        let mapped = ResourceId(0x0010_0a00);
        let unmapped = ResourceId(0x0010_0a01);
        let sub = ResourceId(0x0010_0a02);
        seed_state_window(&mut state, &mut b, mapped, ROOT_WINDOW, 0, 0, 100, 100);
        seed_state_window(&mut state, &mut b, unmapped, ROOT_WINDOW, 0, 0, 100, 100);
        seed_state_window(&mut state, &mut b, sub, mapped, 0, 0, 50, 50);
        let _ = state.resources.map_window(mapped);
        // `unmapped` deliberately left unmapped; `sub` is a child of `mapped`.
        let _ = state.resources.map_window(sub);

        b.sync_top_level_order(&state);

        assert_eq!(
            b.core.top_level_order,
            vec![synth_host_xid(mapped), synth_host_xid(unmapped)],
            "projection keeps unmapped root children (order survives unmap) and \
             excludes subwindows (reached via descendant recursion)"
        );
    }

    // ── Cross-layer agreement regression gates ──
    //
    // These pin scenarios where the core hit-test and the backend
    // hit-test already AGREE today (findings 2026-06-18 §8.1). They are
    // green; the backend demotion must keep them green. Where the red
    // drift1_/drift2_ acceptance tests pin disagreement to be fixed,
    // these pin agreement to be preserved — together they bracket the
    // demotion.

    /// Map a core hit-test result to the synthetic host xid used by
    /// `seed_state_window`, for comparison against backend hit-test results.
    #[cfg(test)]
    fn core_target_host(state: &yserver_core::server::ServerState, x: i16, y: i16) -> Option<u32> {
        state
            .root_pointer_target_at(x, y)
            .map(|(id, _, _)| synth_host_xid(id))
    }

    #[test]
    fn crosslayer_overlapping_top_levels_agree_on_topmost() {
        use yserver_core::resources::ROOT_WINDOW;
        use yserver_protocol::x11::ResourceId;

        let mut state = ServerState::new();
        let mut b = KmsBackend::for_tests();

        // Two fully-overlapping top-levels; `above` created last → topmost
        // in both stores. Default (absent) input shape → both opaque.
        let below = ResourceId(0x0010_0500);
        let above = ResourceId(0x0010_0600);
        seed_state_window(&mut state, &mut b, below, ROOT_WINDOW, 0, 0, 200, 200);
        seed_state_window(&mut state, &mut b, above, ROOT_WINDOW, 0, 0, 200, 200);
        let _ = state.resources.map_window(below);
        let _ = state.resources.map_window(above);
        b.core.top_level_order = vec![synth_host_xid(below), synth_host_xid(above)];
        b.core.cursor_x = 50.0;
        b.core.cursor_y = 50.0;

        // Both layers resolve the topmost overlapping window.
        assert_eq!(
            core_target_host(&state, 50, 50),
            Some(synth_host_xid(above))
        );
        assert_eq!(b.window_under_cursor(), Some(synth_host_xid(above)));
    }

    #[test]
    fn crosslayer_framed_client_both_layers_resolve_client() {
        use yserver_core::resources::ROOT_WINDOW;
        use yserver_protocol::x11::ResourceId;

        let mut state = ServerState::new();
        let mut b = KmsBackend::for_tests();

        // WM frame (top-level) containing a reparented client (subwindow).
        let frame = ResourceId(0x0010_0700);
        let client = ResourceId(0x0010_0701);
        seed_state_window(&mut state, &mut b, frame, ROOT_WINDOW, 0, 0, 300, 300);
        seed_state_window(&mut state, &mut b, client, frame, 10, 10, 100, 100);
        let _ = state.resources.map_window(frame);
        let _ = state.resources.map_window(client);
        // Only the frame is a top-level; the client is a subwindow.
        b.core.top_level_order = vec![synth_host_xid(frame)];
        b.core.cursor_x = 50.0;
        b.core.cursor_y = 50.0;

        // Both layers descend the frame and resolve the deepest hit — the
        // client — and the core maps it back up to the frame top-level.
        assert_eq!(
            core_target_host(&state, 50, 50),
            Some(synth_host_xid(client)),
            "core hit-test descends frame → client"
        );
        assert_eq!(
            b.window_under_cursor(),
            Some(synth_host_xid(client)),
            "backend hit-test descends frame → client"
        );
        assert_eq!(
            state.top_level_for_target(client),
            frame,
            "the client's top-level is the frame"
        );
    }

    /// Synthesise a deterministic host xid for a nested `ResourceId`.
    /// Mirrors the production "high bit set" convention used by the
    /// sibling core tests so the v2 windows keys never collide
    /// with low-numbered nested xids.
    fn synth_host_xid(xid: yserver_protocol::x11::ResourceId) -> u32 {
        0x8000_0000 | xid.0
    }

    /// Seed both the resource-layer `Window` *and* the v2 backend's
    /// `windows` + `store` entries so that:
    /// - `state.resources.window(xid).host_xid` is set,
    /// - `backend.windows[host_xid]` exists with the requested
    ///   geometry, and
    /// - `backend.store.lookup(host_xid)` returns a real
    ///   `DrawableId`.
    fn seed_state_window(
        state: &mut yserver_core::server::ServerState,
        backend: &mut KmsBackend,
        xid: yserver_protocol::x11::ResourceId,
        parent: yserver_protocol::x11::ResourceId,
        x: i16,
        y: i16,
        width: u16,
        height: u16,
    ) {
        use yserver_core::resources::ROOT_WINDOW;
        use yserver_protocol::x11::{ClientId, CreateWindowRequest};
        state.resources.create_window(
            ClientId(14),
            CreateWindowRequest {
                depth: 24,
                window: xid,
                parent,
                x,
                y,
                width,
                height,
                border_width: 0,
                class: 1,
                visual: yserver_core::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );
        let host_xid = synth_host_xid(xid);
        if let Some(w) = state.resources.window_mut(xid) {
            w.host_xid = yserver_core::backend::WindowHandle::from_raw(host_xid);
        }
        // v2 backend's windows + store mirror.
        let parent_host = if parent == ROOT_WINDOW {
            None
        } else {
            Some(synth_host_xid(parent))
        };
        backend.windows.insert(
            host_xid,
            super::WindowGeometry {
                x,
                y,
                width,
                height,
                depth: 24,
                mapped: true,
                parent: parent_host,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        let _ = backend.store.allocate(
            host_xid,
            crate::kms::render::store::DrawableKind::Window,
            24,
            true,
            crate::kms::render::store::Storage::for_tests_null(
                ash::vk::Extent2D {
                    width: u32::from(width.max(1)),
                    height: u32::from(height.max(1)),
                },
                ash::vk::Format::B8G8R8A8_UNORM,
            ),
        );
    }

    /// Allocate a redirected backing for an already-seeded window
    /// and install `set_redirected_target(W, Some(B))` so the
    /// resolver routes paint against `W`'s host xid through `B`.
    /// Also sets the resource-layer `redirected_backing` so the
    /// reconciliation predicates in production code see the
    /// "backing already present" state.
    fn seed_redirected_backing(
        state: &mut yserver_core::server::ServerState,
        backend: &mut KmsBackend,
        xid: yserver_protocol::x11::ResourceId,
    ) {
        let host_xid = synth_host_xid(xid);
        let backing_xid = 0x9000_0000 | xid.0;
        let (width, height, depth) = state
            .resources
            .window(xid)
            .map(|w| (w.width, w.height, w.depth))
            .expect("seed_redirected_backing: window must exist");
        // Allocate the backing in the v2 store.
        let backing_id = backend
            .store
            .allocate(
                backing_xid,
                crate::kms::render::store::DrawableKind::RedirectedBacking,
                depth,
                false,
                crate::kms::render::store::Storage::for_tests_null(
                    ash::vk::Extent2D {
                        width: u32::from(width.max(1)),
                        height: u32::from(height.max(1)),
                    },
                    ash::vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("seed_redirected_backing allocate");
        let w_id = backend
            .store
            .lookup(host_xid)
            .expect("window's drawable id");
        backend.store.set_redirected_target(w_id, Some(backing_id));
        // Mirror on the resource layer so the production
        // reconciliation predicates see a backing present.
        if let Some(w) = state.resources.window_mut(xid) {
            w.redirected_backing = Some(yserver_core::resources::RedirectedBacking {
                host_pixmap: yserver_core::backend::PixmapHandle::from_raw(backing_xid)
                    .expect("non-zero PixmapHandle"),
                width,
                height,
                depth,
            });
        }
    }

    /// Look up the v2 backing `DrawableId` for the redirected
    /// `xid`. Returns `None` if no redirect was installed (or if
    /// the window itself isn't in the store).
    fn backing_drawable_id(
        backend: &KmsBackend,
        xid: yserver_protocol::x11::ResourceId,
    ) -> Option<crate::kms::render::store::DrawableId> {
        let host_xid = synth_host_xid(xid);
        let w_id = backend.store.lookup(host_xid)?;
        backend.store.redirected_target(w_id)
    }

    /// Drive ReparentWindow through the public `process_request`
    /// dispatcher (the v2 backend can't call `handle_reparent_window`
    /// directly — it's `fn`-private to the core_loop module).
    fn dispatch_reparent_window(
        state: &mut yserver_core::server::ServerState,
        backend: &mut KmsBackend,
        window: yserver_protocol::x11::ResourceId,
        parent: yserver_protocol::x11::ResourceId,
        x: i16,
        y: i16,
    ) {
        use yserver_core::{backend::Backend, core_loop::process_request};
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        let mut body = Vec::with_capacity(12);
        body.extend_from_slice(&window.0.to_le_bytes());
        body.extend_from_slice(&parent.0.to_le_bytes());
        body.extend_from_slice(&x.to_le_bytes());
        body.extend_from_slice(&y.to_le_bytes());

        process_request::process_request(
            state,
            backend as &mut dyn Backend,
            ClientId(14),
            SequenceNumber(1),
            RequestHeader {
                opcode: 7, // ReparentWindow
                data: 0,
                length_units: 4,
            },
            &body,
            None,
        )
        .expect("process_request must succeed");
    }

    fn dispatch_configure_window(
        state: &mut yserver_core::server::ServerState,
        backend: &mut KmsBackend,
        window: yserver_protocol::x11::ResourceId,
        x: Option<i16>,
        y: Option<i16>,
        border_width: Option<u16>,
    ) {
        use yserver_core::{backend::Backend, core_loop::process_request};
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        let mut mask = 0u16;
        if x.is_some() {
            mask |= 1 << 0;
        }
        if y.is_some() {
            mask |= 1 << 1;
        }
        if border_width.is_some() {
            mask |= 1 << 4;
        }

        let mut body = Vec::with_capacity(16);
        body.extend_from_slice(&window.0.to_le_bytes());
        body.extend_from_slice(&mask.to_le_bytes());
        body.extend_from_slice(&0u16.to_le_bytes());
        if let Some(x) = x {
            body.extend_from_slice(&(i32::from(x) as u32).to_le_bytes());
        }
        if let Some(y) = y {
            body.extend_from_slice(&(i32::from(y) as u32).to_le_bytes());
        }
        if let Some(border_width) = border_width {
            body.extend_from_slice(&u32::from(border_width).to_le_bytes());
        }

        process_request::process_request(
            state,
            backend as &mut dyn Backend,
            ClientId(14),
            SequenceNumber(1),
            RequestHeader {
                opcode: 12, // ConfigureWindow
                data: 0,
                length_units: u32::try_from((4 + body.len()) / 4).expect("request length"),
            },
            &body,
            None,
        )
        .expect("process_request(ConfigureWindow) must succeed");
    }

    fn dispatch_poly_fill_rectangle(
        state: &mut yserver_core::server::ServerState,
        backend: &mut KmsBackend,
        drawable: yserver_protocol::x11::ResourceId,
        gc: yserver_protocol::x11::ResourceId,
        rects: &[Rectangle16],
    ) {
        use yserver_core::{backend::Backend, core_loop::process_request};
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        let mut body = Vec::with_capacity(8 + rects.len() * 8);
        body.extend_from_slice(&drawable.0.to_le_bytes());
        body.extend_from_slice(&gc.0.to_le_bytes());
        for rect in rects {
            body.extend_from_slice(&rect.x.to_le_bytes());
            body.extend_from_slice(&rect.y.to_le_bytes());
            body.extend_from_slice(&rect.width.to_le_bytes());
            body.extend_from_slice(&rect.height.to_le_bytes());
        }

        process_request::process_request(
            state,
            backend as &mut dyn Backend,
            ClientId(14),
            SequenceNumber(1),
            RequestHeader {
                opcode: 70, // PolyFillRectangle
                data: 0,
                length_units: u32::try_from((4 + body.len()) / 4).expect("request length"),
            },
            &body,
            None,
        )
        .expect("process_request(PolyFillRectangle) must succeed");
    }

    fn create_live_window(
        state: &mut yserver_core::server::ServerState,
        backend: &mut KmsBackend,
        xid: yserver_protocol::x11::ResourceId,
        parent: yserver_protocol::x11::ResourceId,
        x: i16,
        y: i16,
        width: u16,
        height: u16,
    ) -> yserver_core::backend::WindowHandle {
        use yserver_core::{
            backend::Backend,
            host_x11::HostSubwindowVisual,
            resources::{ROOT_VISUAL, ROOT_WINDOW},
        };
        use yserver_protocol::x11::ClientId;

        state.resources.create_window(
            ClientId(14),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: xid,
                parent,
                x,
                y,
                width,
                height,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );

        let host_parent = if parent == ROOT_WINDOW {
            yserver_core::backend::WindowHandle::from_raw(backend.core.window_id).expect("root")
        } else {
            state
                .resources
                .window(parent)
                .and_then(|w| w.host_xid)
                .expect("parent host_xid")
        };
        let host = backend
            .create_subwindow(
                None,
                host_parent,
                x,
                y,
                width,
                height,
                0,
                HostSubwindowVisual::Explicit {
                    depth: 24,
                    visual_xid: 0,
                    colormap_xid: 0,
                },
                None,
                None,
            )
            .expect("create_subwindow");
        state.resources.window_mut(xid).expect("window").host_xid = Some(host);
        if parent == ROOT_WINDOW {
            backend
                .register_top_level(None, xid, host.as_raw())
                .expect("register_top_level");
        } else {
            backend
                .register_subwindow(None, xid, host.as_raw())
                .expect("register_subwindow");
        }
        let _ = state.resources.map_window(xid);
        backend
            .map_subwindow(None, host.as_raw())
            .expect("map_subwindow");
        host
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn process_request_root_fill_include_inferiors_matches_top_level_after_move() {
        use yserver_core::resources::ROOT_WINDOW;
        use yserver_protocol::x11::{ClientId, CreateGcRequest, ResourceId};

        let mut state = yserver_core::server::ServerState::new();
        let mut backend = match KmsBackend::for_tests_with_vk() {
            Ok(b) => b,
            Err(e) => {
                eprintln!("skipping: no Vk: {e}");
                return;
            }
        };
        install_client_for_render(&mut state, 14);
        state
            .resources
            .window_mut(ROOT_WINDOW)
            .expect("root")
            .host_xid = yserver_core::backend::WindowHandle::from_raw(backend.core.window_id);

        let top = ResourceId(0x2000);
        let gc = ResourceId(0x2001);
        let child_base = 0x2100u32;
        let grandchild_base = 0x2200u32;

        let top_host =
            create_live_window(&mut state, &mut backend, top, ROOT_WINDOW, 11, 7, 100, 90);
        let top_xid = top_host.as_raw();

        backend
            .fill_rectangle(None, top_xid, 0x0000_0000, 0, 0, 100, 90)
            .expect("clear top");
        backend
            .fill_rectangle(None, top_xid, 0x0000_00ff, 20, 30, 70, 30)
            .expect("baseline fill");
        let expected = backend
            .get_image_pixels_for_tests(top_xid, 2, 0, 0, 100, 90, !0)
            .expect("baseline get_image")
            .expect("baseline bytes");
        backend
            .fill_rectangle(None, top_xid, 0x0000_0000, 0, 0, 100, 90)
            .expect("re-clear top");

        state.resources.create_gc(
            ClientId(14),
            CreateGcRequest {
                gc,
                drawable: top,
                function: None,
                plane_mask: None,
                foreground: Some(0x0000_00ff),
                background: None,
                line_width: None,
                line_style: None,
                cap_style: None,
                join_style: None,
                fill_style: None,
                fill_rule: None,
                tile: None,
                stipple: None,
                tile_x_origin: None,
                tile_y_origin: None,
                font: None,
                subwindow_mode: Some(1),
                graphics_exposures: None,
                clip_x_origin: None,
                clip_y_origin: None,
                clip_mask: None,
                dash_offset: None,
                dashes: None,
                arc_mode: None,
            },
        );

        for i in 0..4 {
            let child = ResourceId(child_base + i);
            create_live_window(
                &mut state,
                &mut backend,
                child,
                top,
                (i * 20) as i16,
                0,
                10,
                90,
            );
            for j in 0..9 {
                create_live_window(
                    &mut state,
                    &mut backend,
                    ResourceId(grandchild_base + i * 16 + j),
                    child,
                    0,
                    (j * 10) as i16,
                    10,
                    6,
                );
            }
        }

        let rect = [Rectangle16 {
            x: 20,
            y: 30,
            width: 70,
            height: 30,
        }];

        dispatch_poly_fill_rectangle(&mut state, &mut backend, top, gc, &rect);
        let top_include = backend
            .get_image_pixels_for_tests(top_xid, 2, 0, 0, 100, 90, !0)
            .expect("top include get_image")
            .expect("top include bytes");
        assert_eq!(
            top_include, expected,
            "top-level request path must match baseline"
        );

        backend
            .fill_rectangle(None, top_xid, 0x0000_0000, 0, 0, 100, 90)
            .expect("re-clear top");

        dispatch_configure_window(&mut state, &mut backend, top, Some(0), Some(0), Some(0));

        let geom = backend.windows.get(&top_xid).expect("top geom after move");
        assert_eq!(
            (geom.x, geom.y),
            (0, 0),
            "backend geometry must track ConfigureWindow"
        );

        dispatch_poly_fill_rectangle(&mut state, &mut backend, ROOT_WINDOW, gc, &rect);
        let root_out = backend
            .get_image_pixels_for_tests(top_xid, 2, 0, 0, 100, 90, !0)
            .expect("root-path get_image")
            .expect("root-path bytes");
        assert_eq!(root_out, expected);
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn root_get_image_reads_scanout_pixels_not_root_storage() {
        use ash::vk;
        use yserver_core::{resources::ROOT_WINDOW, server::ServerState};
        use yserver_protocol::x11::ResourceId;

        let mut state = ServerState::new();
        let mut backend = match KmsBackend::for_tests_with_vk_live_scene() {
            Ok(b) => b,
            Err(e) => {
                eprintln!("skipping: no Vk: {e}");
                return;
            }
        };
        install_client_for_render(&mut state, 14);
        state
            .resources
            .window_mut(ROOT_WINDOW)
            .expect("root")
            .host_xid = yserver_core::backend::WindowHandle::from_raw(backend.core.window_id);

        let (root_w, root_h) = {
            let root = state.resources.window(ROOT_WINDOW).expect("root window");
            (root.width, root.height)
        };
        let window = ResourceId(0x2002);
        let window_host = create_live_window(
            &mut state,
            &mut backend,
            window,
            ROOT_WINDOW,
            32,
            24,
            16,
            16,
        );

        let root_color = 0x0011_2233;
        let window_color = 0x00aa_55ff;
        backend
            .fill_rectangle(
                None,
                backend.core.window_id,
                root_color,
                0,
                0,
                root_w,
                root_h,
            )
            .expect("fill root");
        backend
            .fill_rectangle(None, window_host.as_raw(), window_color, 0, 0, 16, 16)
            .expect("fill window");
        backend.tick_maybe_composite_for_tests();

        let scan_rect = vk::Rect2D {
            offset: vk::Offset2D { x: 32, y: 24 },
            extent: vk::Extent2D {
                width: 16,
                height: 16,
            },
        };
        let scanout = super::read_scanout_region(
            &mut backend,
            scan_rect,
            super::ScanoutReadSelection::OnScreenOnly,
        )
        .expect("scanout readback");
        let root_out = backend
            .get_image_pixels_for_tests(backend.core.window_id, 2, 32, 24, 16, 16, !0)
            .expect("root get_image")
            .expect("root bytes");
        let window_out = backend
            .get_image_pixels_for_tests(window_host.as_raw(), 2, 0, 0, 16, 16, !0)
            .expect("window get_image")
            .expect("window bytes");

        assert_eq!(
            root_out, scanout,
            "root GetImage must read the on-screen scanout"
        );
        assert_eq!(
            root_out, window_out,
            "root GetImage must match the visible window pixels"
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn root_overlay_xor_pass_reaches_scanout() {
        // Task 6: the retained root-`IncludeInferiors` overlay is applied
        // as an XOR pass at the END of compose, into the freshly-
        // composited scanout BO. Drive one compose with the whole root
        // filled a uniform color and an Invert (`value = plane_mask`)
        // overlay toggled over ONE sub-region, then read the scanout back:
        // the overlaid region must differ from an identically-filled
        // control region that has no overlay (i.e. the XOR reached the
        // scanout), while the control region reflects the untouched fill.
        use ash::vk;
        use yserver_core::{resources::ROOT_WINDOW, server::ServerState};
        use yserver_protocol::x11::ClientId;

        let mut state = ServerState::new();
        let mut backend = match KmsBackend::for_tests_with_vk_live_scene() {
            Ok(b) => b,
            Err(e) => {
                eprintln!("skipping: no Vk: {e}");
                return;
            }
        };
        install_client_for_render(&mut state, 14);
        state
            .resources
            .window_mut(ROOT_WINDOW)
            .expect("root")
            .host_xid = yserver_core::backend::WindowHandle::from_raw(backend.core.window_id);

        let (root_w, root_h) = {
            let root = state.resources.window(ROOT_WINDOW).expect("root window");
            (root.width, root.height)
        };

        // Uniform root fill so the overlaid region and the control region
        // start from the same pixels.
        let root_color = 0x0033_5577;
        backend
            .fill_rectangle(
                None,
                backend.core.window_id,
                root_color,
                0,
                0,
                root_w,
                root_h,
            )
            .expect("fill root");

        // Overlay region + an identically-filled control region.
        let overlay_rect = vk::Rect2D {
            offset: vk::Offset2D { x: 20, y: 20 },
            extent: vk::Extent2D {
                width: 60,
                height: 60,
            },
        };
        let control_rect = vk::Rect2D {
            offset: vk::Offset2D { x: 200, y: 20 },
            extent: vk::Extent2D {
                width: 60,
                height: 60,
            },
        };

        // Invert: xor_value = plane_mask (24-bit). Injects damage so the
        // compose actually runs over the region.
        let xor_value = 0x00ff_ffff;
        backend
            .scene
            .root_overlay_toggle(ClientId(14), xor_value, &[overlay_rect]);
        assert!(
            !backend.scene.root_overlay.is_empty(),
            "overlay op must be retained"
        );

        backend.tick_maybe_composite_for_tests();

        let overlaid = super::read_scanout_region(
            &mut backend,
            overlay_rect,
            super::ScanoutReadSelection::OnScreenOnly,
        )
        .expect("scanout readback (overlay)");
        let control = super::read_scanout_region(
            &mut backend,
            control_rect,
            super::ScanoutReadSelection::OnScreenOnly,
        )
        .expect("scanout readback (control)");

        assert!(
            !overlaid.is_empty() && !control.is_empty(),
            "non-empty reads"
        );
        assert_eq!(
            overlaid.len(),
            control.len(),
            "same-size regions read same byte count"
        );
        assert_ne!(
            overlaid, control,
            "XOR overlay pass must have changed the overlaid scanout region \
             relative to the identically-filled control region"
        );
        // Control region is uniform (the untouched fill): every pixel equals
        // the first, confirming the compose ran and only the overlay region
        // was toggled.
        let px = &control[0..4];
        assert!(
            control.chunks_exact(4).all(|c| c == px),
            "control region must be the uniform root fill (overlay must not \
             have touched it)"
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn root_copy_area_include_inferiors_captures_window_into_pixmap() {
        use yserver_core::{backend::SubwindowMode, resources::ROOT_WINDOW, server::ServerState};
        use yserver_protocol::x11::ResourceId;

        let mut state = ServerState::new();
        let mut backend = match KmsBackend::for_tests_with_vk_live_scene() {
            Ok(b) => b,
            Err(e) => {
                eprintln!("skipping: no Vk: {e}");
                return;
            }
        };
        install_client_for_render(&mut state, 14);
        state
            .resources
            .window_mut(ROOT_WINDOW)
            .expect("root")
            .host_xid = yserver_core::backend::WindowHandle::from_raw(backend.core.window_id);

        let (root_w, root_h) = {
            let root = state.resources.window(ROOT_WINDOW).expect("root window");
            (root.width, root.height)
        };
        let window = ResourceId(0x2002);
        let window_host = create_live_window(
            &mut state,
            &mut backend,
            window,
            ROOT_WINDOW,
            32,
            24,
            16,
            16,
        );

        let root_color = 0x0011_2233;
        let window_color = 0x00aa_55ff;
        backend
            .fill_rectangle(
                None,
                backend.core.window_id,
                root_color,
                0,
                0,
                root_w,
                root_h,
            )
            .expect("fill root");
        backend
            .fill_rectangle(None, window_host.as_raw(), window_color, 0, 0, 16, 16)
            .expect("fill window");
        backend.tick_maybe_composite_for_tests();

        // Screenshot path: CopyArea(src=root, dst=pixmap) with a GC whose
        // subwindow-mode is IncludeInferiors (Qt5 QScreen::grabWindow).
        let dst = backend
            .create_pixmap(None, 24, root_w, root_h)
            .expect("create destination pixmap");
        backend.core.current_subwindow_mode = SubwindowMode::IncludeInferiors;
        backend
            .copy_area(
                None,
                backend.core.window_id,
                dst.as_raw(),
                0,
                0,
                0,
                0,
                root_w,
                root_h,
            )
            .expect("copy root to pixmap");

        // The mapped window's region in the destination must carry the
        // composited WINDOW pixels, not the root background. On the buggy
        // path copy_area reads root STORAGE (background), so this region
        // comes back as root_color and the assert fails.
        let win_region = backend
            .get_image_pixels_for_tests(dst.as_raw(), 2, 32, 24, 16, 16, !0)
            .expect("dst get_image window region")
            .expect("dst window bytes");
        let scanout_win = super::read_scanout_region(
            &mut backend,
            ash::vk::Rect2D {
                offset: ash::vk::Offset2D { x: 32, y: 24 },
                extent: ash::vk::Extent2D {
                    width: 16,
                    height: 16,
                },
            },
            super::ScanoutReadSelection::OnScreenOnly,
        )
        .expect("scanout readback");
        assert_eq!(
            win_region, scanout_win,
            "root CopyArea(IncludeInferiors) must copy the composited desktop \
             (window pixels), not the root background"
        );

        // A region with no window on top must still carry the root background.
        let bg_region = backend
            .get_image_pixels_for_tests(dst.as_raw(), 2, 0, 0, 8, 8, !0)
            .expect("dst get_image bg region")
            .expect("dst bg bytes");
        let scanout_bg = super::read_scanout_region(
            &mut backend,
            ash::vk::Rect2D {
                offset: ash::vk::Offset2D { x: 0, y: 0 },
                extent: ash::vk::Extent2D {
                    width: 8,
                    height: 8,
                },
            },
            super::ScanoutReadSelection::OnScreenOnly,
        )
        .expect("scanout bg readback");
        assert_eq!(
            bg_region, scanout_bg,
            "root CopyArea(IncludeInferiors) must copy the background where no window covers"
        );
    }

    fn r(x: i32, y: i32, w: u32, h: u32) -> ash::vk::Rect2D {
        ash::vk::Rect2D {
            offset: ash::vk::Offset2D { x, y },
            extent: ash::vk::Extent2D {
                width: w,
                height: h,
            },
        }
    }

    #[test]
    fn split_root_scanout_reads_single_output_whole_rect() {
        let got =
            super::split_root_scanout_reads(r(0, 0, 100, 50), 0, 0, 0, 0, &[(0, 0, 200, 200)]);
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].read, r(0, 0, 100, 50));
        assert_eq!(got[0].dst_local, ash::vk::Offset2D { x: 0, y: 0 });
    }

    #[test]
    fn split_root_scanout_reads_honors_src_origin() {
        // Copy from root (32,24) into dst (0,0): read root-absolute (32,24),
        // write to dst-local (0,0).
        let got =
            super::split_root_scanout_reads(r(0, 0, 16, 16), 32, 24, 0, 0, &[(0, 0, 800, 600)]);
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].read, r(32, 24, 16, 16));
        assert_eq!(got[0].dst_local, ash::vk::Offset2D { x: 0, y: 0 });
    }

    #[test]
    fn split_root_scanout_reads_spanning_two_outputs() {
        // Full 200x100 grab across two 100-wide side-by-side outputs → two reads.
        let got = super::split_root_scanout_reads(
            r(0, 0, 200, 100),
            0,
            0,
            0,
            0,
            &[(0, 0, 100, 100), (100, 0, 100, 100)],
        );
        assert_eq!(got.len(), 2);
        assert_eq!(got[0].read, r(0, 0, 100, 100));
        assert_eq!(got[0].dst_local, ash::vk::Offset2D { x: 0, y: 0 });
        assert_eq!(got[1].read, r(100, 0, 100, 100));
        assert_eq!(got[1].dst_local, ash::vk::Offset2D { x: 100, y: 0 });
    }

    #[test]
    fn split_root_scanout_reads_clips_partially_offscreen() {
        // Requested 200x200 but output is only 150x120: read the covered piece.
        let got =
            super::split_root_scanout_reads(r(0, 0, 200, 200), 0, 0, 0, 0, &[(0, 0, 150, 120)]);
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].read, r(0, 0, 150, 120));
        assert_eq!(got[0].dst_local, ash::vk::Offset2D { x: 0, y: 0 });
    }

    #[test]
    fn split_root_scanout_reads_fully_offscreen_is_empty() {
        let got =
            super::split_root_scanout_reads(r(0, 0, 50, 50), 500, 500, 0, 0, &[(0, 0, 100, 100)]);
        assert!(got.is_empty());
    }

    #[test]
    fn assemble_root_scanout_spans_two_outputs() {
        // Two 2x2 outputs side by side; a full 4x2 root region. Left output's
        // read returns solid 0x11, right returns 0x22. The assembled buffer must
        // carry each output's pixels in its half — the exact dual-monitor case
        // the old single-`read_scanout_region` path returned all-black for
        // (rect spanning two outputs → no matching BO → empty reply).
        let outputs = [(0i32, 0i32, 2u32, 2u32), (2, 0, 2, 2)];
        let got = super::assemble_root_scanout(r(0, 0, 4, 2), &outputs, |rect| {
            let px = (rect.extent.width * rect.extent.height) as usize;
            let byte = if rect.offset.x == 0 { 0x11u8 } else { 0x22u8 };
            Some(vec![byte; px * 4])
        });
        assert_eq!(got.len(), 4 * 2 * 4);
        // stride = 4 px * 4 bytes = 16. Left 2 px (8 bytes) then right 2 px.
        assert_eq!(&got[0..8], &[0x11u8; 8], "row0 left half from output 0");
        assert_eq!(&got[8..16], &[0x22u8; 8], "row0 right half from output 1");
        assert_eq!(&got[16..24], &[0x11u8; 8], "row1 left half from output 0");
        assert_eq!(&got[24..32], &[0x22u8; 8], "row1 right half from output 1");
    }

    #[test]
    fn assemble_root_scanout_failed_read_is_zero_filled() {
        // A piece whose read fails stays zero (black) instead of aborting the
        // whole capture; the covered output still lands.
        let outputs = [(0i32, 0i32, 2u32, 2u32), (2, 0, 2, 2)];
        let got = super::assemble_root_scanout(r(0, 0, 4, 1), &outputs, |rect| {
            if rect.offset.x == 0 {
                Some(vec![
                    0x11u8;
                    (rect.extent.width * rect.extent.height) as usize * 4
                ])
            } else {
                None
            }
        });
        assert_eq!(&got[0..8], &[0x11u8; 8], "covered output landed");
        assert_eq!(&got[8..16], &[0x00u8; 8], "failed-read output stays black");
    }

    #[test]
    fn split_root_scanout_reads_output_offset_shifts_dst_local() {
        // Output starts at x=50: the left half (root x 0..50) is off-screen and
        // dropped; the right half reads root x50.. and writes to dst-local x50.
        let got =
            super::split_root_scanout_reads(r(0, 0, 100, 100), 0, 0, 0, 0, &[(50, 0, 800, 600)]);
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].read, r(50, 0, 50, 100));
        assert_eq!(got[0].dst_local, ash::vk::Offset2D { x: 50, y: 0 });
    }

    #[test]
    fn split_root_scanout_reads_carries_subrect_dst_offset() {
        // A GC-clip sub-rect at dst-local (20,10): source tracks it, dst-local
        // offset is preserved.
        let got =
            super::split_root_scanout_reads(r(20, 10, 30, 30), 0, 0, 0, 0, &[(0, 0, 800, 600)]);
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].read, r(20, 10, 30, 30));
        assert_eq!(got[0].dst_local, ash::vk::Offset2D { x: 20, y: 10 });
    }

    /// Register a client in `state.clients` so `process_request`'s
    /// per-client sequence stamp + (potential) error-emission path
    /// have a real `ClientState` to operate on. Uses
    /// `resource_id_mask = u32::MAX` so the fixture xids are
    /// trivially in-range.
    fn install_client_for_render(state: &mut yserver_core::server::ServerState, id: u32) {
        use std::{
            collections::{HashMap, HashSet, VecDeque},
            os::unix::net::UnixStream,
            sync::{Arc, Mutex, atomic::AtomicU16},
        };
        use yserver_core::{resources::ROOT_WINDOW, server::ClientState};
        use yserver_protocol::x11::ClientByteOrder;
        let (a, _b) = UnixStream::pair().unwrap();
        state.clients.insert(
            id,
            ClientState {
                writer: Arc::new(Mutex::new(a)),
                byte_order: ClientByteOrder::LittleEndian,
                last_sequence: Arc::new(AtomicU16::new(0)),
                resource_id_base: 0,
                resource_id_mask: u32::MAX,
                event_masks: HashMap::new(),
                save_set: HashSet::new(),
                big_requests_enabled: false,
                xi2_masks: HashMap::new(),
                xi1_event_classes: HashSet::new(),
                xi1_window_event_classes: HashMap::new(),
                outbound: VecDeque::new(),
                watching_writable: false,
                focused_window: ROOT_WINDOW,
                reader_control: None,
            },
        );
    }

    #[test]
    fn resolve_paint_target_after_reparent_out_routes_to_new_redirected_ancestor() {
        use yserver_core::{
            resources::ROOT_WINDOW,
            server::{CompositeRedirectMode, RedirectRecord, ServerState},
        };
        use yserver_protocol::x11::{ClientId, ResourceId};

        // Phase 2 root-cause pin: build a tree mirroring the live
        // mate-panel case (root → mate-panel, root → nm-applet),
        // dispatch a ReparentWindow that moves nm-applet under
        // mate-panel's socket, then assert resolve_paint_target
        // returns mate-panel's backing with the right offset.
        //
        // Pre-fix: nm-applet's stale Manual-redirect backing wins,
        // resolve_paint_target returns it with offset (0, 0).
        // Post-fix (handle_reparent_window's reconciliation): the
        // backing is freed, resolve_paint_target walks up the
        // ancestor chain to mate-panel's backing with the offset
        // = nm-applet's screen-coord position within mate-panel.

        let mut state = ServerState::new();
        let mut backend = KmsBackend::for_tests();
        install_client_for_render(&mut state, 14);

        let root_xid = ROOT_WINDOW;
        let mate_panel_xid = ResourceId(0x110_0003);
        let socket_xid = ResourceId(0x210_0013);
        let nm_applet_xid = ResourceId(0x180_000b);

        // Pre-state: root has RedirectSubwindows(Manual). mate-panel
        // is a redirected direct child. socket is a child of mate-
        // panel (not directly redirected). nm-applet is currently
        // a direct child of root (and therefore inherits redirect).
        state.composite_redirects.insert(
            (root_xid, true),
            RedirectRecord {
                mode: CompositeRedirectMode::Manual,
                owner: ClientId(14),
            },
        );

        seed_state_window(
            &mut state,
            &mut backend,
            mate_panel_xid,
            root_xid,
            0,
            0,
            2560,
            28,
        );
        seed_redirected_backing(&mut state, &mut backend, mate_panel_xid);
        let mate_panel_backing_id =
            backing_drawable_id(&backend, mate_panel_xid).expect("mate-panel backing drawable id");
        seed_state_window(
            &mut state,
            &mut backend,
            socket_xid,
            mate_panel_xid,
            2387,
            0,
            26,
            27,
        );
        seed_state_window(
            &mut state,
            &mut backend,
            nm_applet_xid,
            root_xid,
            0,
            0,
            26,
            27,
        );
        seed_redirected_backing(&mut state, &mut backend, nm_applet_xid);

        dispatch_reparent_window(
            &mut state,
            &mut backend,
            nm_applet_xid,
            socket_xid,
            /* x */ 0,
            /* y */ 0,
        );

        let nm_applet_host_xid = synth_host_xid(nm_applet_xid);

        let resolved = backend
            .resolve_paint_target(nm_applet_host_xid)
            .expect("resolve must succeed");

        assert_eq!(
            resolved.id, mate_panel_backing_id,
            "paints into nm-applet must route to mate-panel's redirected backing post-reparent"
        );
        assert_eq!(
            resolved.offset,
            (2387, 0),
            "offset must place the paint at nm-applet's screen-coord position within mate-panel's backing"
        );
    }

    /// Stage 5 Task 6.1 (foundation prereq #2): the by-handle xshmfence
    /// accessor returns an Arc clone that pins the underlying
    /// `FenceMapping` alive past `XFixesDestroyFence` (registry
    /// removal). Two clones plus the registry entry should give a
    /// strong count of 3; after removing the registry entry the
    /// caller-held clones still keep the primitive alive (Drop sees a
    /// non-shared Arc).
    #[test]
    fn xshmfence_handle_accessor_returns_arc_clone() {
        // Construct a backend without Vk (skip if test fixture needs it).
        let mut b = match crate::kms::render::KmsBackend::for_tests_with_vk() {
            Ok(b) => b,
            Err(e) => {
                eprintln!("skipping: no Vk: {e}");
                return;
            }
        };
        // Manually inject an entry into the registry — bypass the
        // protocol path (DRI3 FenceFromFD) since constructing a real
        // xshmfence FD in a unit test is fragile.
        let xid = 0x1234_5678_u32;
        let mapping = crate::kms::xshmfence::FenceMapping::for_tests_dummy();
        b.dri3_xshmfences.insert(xid, std::sync::Arc::new(mapping));
        let h1 = b.dri3_xshmfence_handle(xid).expect("handle present");
        assert_eq!(
            std::sync::Arc::strong_count(&h1),
            2,
            "registry + caller should both hold a reference"
        );
        let h2 = b.dri3_xshmfence_handle(xid).expect("second handle");
        assert_eq!(
            std::sync::Arc::strong_count(&h1),
            3,
            "registry + two callers should all hold references"
        );
        let _ = h1;
        let _ = h2;
        // Drop the registry entry (mimics XFixesDestroyFence).
        b.dri3_xshmfences.remove(&xid);
        // Accessor returns None now; but the caller's Arc clones
        // still pin the FenceMapping alive (no destructor panic).
        assert!(b.dri3_xshmfence_handle(xid).is_none());
    }

    /// Phase B.2 Task 14: three `render_composite` calls in the same
    /// open frame, then a forced close. After the backend drains the
    /// queued `FrameCloseEvent` into telemetry, the lifetime
    /// `frame_builder_renders_per_frame_max_in_window` gauge must
    /// reflect ≥ 3 (the count of `RecordedOp::RenderComposite` ops
    /// recorded into the closing frame). Exercises the full path:
    /// engine populates `renders_in_frame` at the close-event push
    /// site → backend's `drain_frame_builder_telemetry` reads it →
    /// `record_frame_builder_close` accumulates into the bucket +
    /// lifetime gauges.
    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn frame_builder_renders_per_frame_telemetry_records_max() {
        let mut be = match KmsBackend::for_tests_with_vk() {
            Ok(b) => b,
            Err(e) => {
                eprintln!("skipping: no Vk: {e}");
                return;
            }
        };

        let dst = be
            .allocate_test_pixmap_bgra(64, 64)
            .expect("allocate_test_pixmap_bgra");

        // Drain any baseline close events from pixmap allocation so the
        // lifetime gauge snapshot is taken at a clean baseline.
        be.engine_flush_submit_group_for_tests()
            .expect("setup drain");

        // Three solid-fill composites into the same dst. All three ops
        // append into the same open frame under the sub-gate.
        let r1 = be.render_composite_for_tests(dst, [1.0, 0.0, 0.0, 1.0], 64, 64);
        let r2 = be.render_composite_for_tests(dst, [0.0, 1.0, 0.0, 1.0], 64, 64);
        let r3 = be.render_composite_for_tests(dst, [0.0, 0.0, 1.0, 1.0], 64, 64);

        // Force frame close via the Timeout helper; this runs the
        // close-walk that pushes the FrameCloseEvent.
        let close_result = be.engine_close_open_frame_for_timeout_for_tests();

        // Reset the process-level sub-gate IMMEDIATELY so neighbouring
        // tests in the same cargo-test binary are not routed through
        // the frame-builder composite path.

        r1.expect("first render_composite_for_tests");
        r2.expect("second render_composite_for_tests");
        r3.expect("third render_composite_for_tests");
        close_result.expect("engine_close_open_frame_for_timeout_for_tests");

        // Drain queued FrameCloseEvent → telemetry. Reuse the existing
        // helper that drains flush outcomes + close events as a side
        // effect of returning submit_group_flushes.
        let _ = be.telemetry_submit_group_flushes_for_tests();
        be.drain_frame_builder_telemetry_for_tests();

        assert!(
            be.telemetry
                .lifetime
                .frame_builder_renders_per_frame_max_in_window
                >= 3,
            "lifetime renders_per_frame_max_in_window must reflect the \
             three RenderComposite ops recorded in the closing frame; got {}",
            be.telemetry
                .lifetime
                .frame_builder_renders_per_frame_max_in_window,
        );
    }

    #[test]
    #[ignore = "needs a DRM render node"]
    fn syncobj_handle_accessor_returns_arc_clone() {
        // Shared helper from Task 1 — never hardcode renderD128.
        let Some(drm) = crate::kms::render::imported_syncobj::tests::render_node() else {
            eprintln!("skipping: no render node");
            return;
        };
        let handle =
            ::drm::control::Device::create_syncobj(drm.as_ref(), false).expect("create syncobj");
        let fd =
            ::drm::control::Device::syncobj_to_fd(drm.as_ref(), handle, false).expect("export fd");

        let mut b = KmsBackend::for_tests();
        let xid = 0xAAAA_BBBB_u32;
        b.dri3_syncobjs.insert(
            xid,
            (
                yserver_protocol::x11::ClientId(1),
                std::sync::Arc::new(
                    crate::kms::render::imported_syncobj::ImportedSyncobj::import(
                        drm.clone(),
                        std::os::fd::AsFd::as_fd(&fd),
                    )
                    .expect("import"),
                ),
            ),
        );

        let h = b.dri3_syncobj_handle(xid).expect("handle present");
        assert_eq!(std::sync::Arc::strong_count(&h), 2);
        b.dri3_syncobjs.remove(&xid);
        // Accessor returns None now; the held Arc still pins the resource
        // alive, which is what the deferred completion path relies on.
        assert!(b.dri3_syncobj_handle(xid).is_none());
        drop(h);

        ::drm::control::Device::destroy_syncobj(drm.as_ref(), handle).expect("destroy");
    }

    // ─── Task 10: held-key tracking + synthesize-releases tests ───

    /// `on_host_input` Key arm maintains `down_keys`: press inserts the
    /// cooked keycode, release removes it. Tests the additive tracking
    /// path without touching fanout behaviour.
    #[test]
    fn down_keys_maintained_on_key_press_and_release() {
        use yserver_core::{
            core_loop::HostInputEvent, host_x11::HostKeyEvent, server::ServerState,
        };
        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();

        let raw_press = HostKeyEvent {
            keycode: 38, // evdev 'a' (US layout)
            pressed: true,
            state: 0,
            root_x: 0,
            root_y: 0,
            event_x: 0,
            event_y: 0,
            time: 0,
        };
        b.on_host_input(&mut state, HostInputEvent::Key(raw_press));
        assert!(
            b.core.down_keys.contains(&38),
            "key 38 must be in down_keys after press"
        );
        assert_eq!(b.core.down_keys.len(), 1);

        let raw_release = HostKeyEvent {
            keycode: 38,
            pressed: false,
            state: 0,
            root_x: 0,
            root_y: 0,
            event_x: 0,
            event_y: 0,
            time: 0,
        };
        b.on_host_input(&mut state, HostInputEvent::Key(raw_release));
        assert!(
            !b.core.down_keys.contains(&38),
            "key 38 must be removed from down_keys after release"
        );
        assert!(b.core.down_keys.is_empty());
    }

    /// `synthesize_held_releases` clears `down_keys` and `button_mask`,
    /// emits a synthetic release for every tracked key and button, and
    /// leaves `pending_pointer_events` empty.
    ///
    /// Behavioural contract:
    /// (a) `down_keys` empty after the call
    /// (b) `button_mask == 0` after the call
    /// (c) `pending_pointer_events` drained (button releases fanned out)
    /// (d) No XI2 raw event is generated (key_event_fanout_to_state
    ///     does not emit XI2 raw events — this is a property of the
    ///     fanout, not separately asserted here)
    ///
    /// Note: with a fresh `ServerState::new()` there are no subscribed
    /// clients, so key/button events are dropped by the fanout (no
    /// receivers). The load-bearing observables are the state fields:
    /// `down_keys` empty proves every held key was iterated, and
    /// `button_mask == 0` proves every held button's bit was cleared
    /// by its corresponding `process_pointer_button(released)` call.
    #[test]
    fn synthesize_held_releases_clears_down_keys_and_button_mask() {
        use yserver_core::server::ServerState;
        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();

        // Inject two held keys directly into down_keys (bypassing
        // cook_host_key so we control exact keycodes).
        b.core.down_keys.insert(38); // 'a'
        b.core.down_keys.insert(56); // 'b'
        assert_eq!(b.core.down_keys.len(), 2);

        // Inject held buttons 1 (BTN_LEFT, bit 0x0100) and 3
        // (BTN_RIGHT, bit 0x0400) into button_mask.
        b.core.button_mask = 0x0100 | 0x0400;
        assert_ne!(b.core.button_mask, 0);

        b.synthesize_held_releases(&mut state);

        // (a) down_keys cleared.
        assert!(
            b.core.down_keys.is_empty(),
            "down_keys must be empty after synthesize_held_releases"
        );
        // (b) button_mask zeroed.
        assert_eq!(
            b.core.button_mask, 0,
            "button_mask must be 0 after synthesize_held_releases"
        );
        // (c) pending_pointer_events drained.
        assert!(
            b.core.pending_pointer_events.is_empty(),
            "pending_pointer_events must be empty (fanned out) after synthesize_held_releases"
        );
    }

    // ── Task 13: stub-backed VT-switch suspend/resume integration tests ──
    //
    // These tests drive `inject_seat_event_for_test` directly — no DRM, no
    // real hardware. They exercise the full state-machine path
    // plus `run_suspend` side-effects that are reachable in the stub harness.
    //
    // Resume path note: the ordinary fixture's synthetic `/dev/null` DRM
    // device fails connector probing. That failure must leave the state in
    // `Resuming` with scanout closed; production concurrently requests a
    // process exit. Tests that need a successful logical VT cycle convert the
    // fixture to the supported zero-device headless configuration first.

    fn make_vt_fixture_headless(b: &mut KmsBackend) {
        b.platform.devices.clear();
        b.platform.outputs.clear();
        b.platform.scanout_pools.clear();
        b.platform.bo_generations.clear();
        b.platform.first_pageflip_logged.clear();
        b.platform.fb_w = 0;
        b.platform.fb_h = 0;
        b.kms_outputs_active = false;
        b.scene
            .rebuild_outputs(&b.platform)
            .expect("headless scene rebuild");
    }

    /// A screensaver blank that lands after a VT switch away used to issue a
    /// modeset while we no longer held DRM master, failing with EACCES
    /// part-way through `dpms_set_outputs_active` and leaving
    /// `kms_outputs_active` disagreeing with the hardware. Reported on
    /// discussion #79 (Alpine/AMD GX-424CC): `libseat disable() ok` followed by
    /// `disable_output for eDP-1 failed: ... Permission denied (os error 13)`.
    /// `scanout_allowed()` is the documented gate for master-requiring work.
    #[test]
    fn set_dpms_power_is_skipped_while_suspended_and_failed_resume_stays_closed() {
        use crate::vt::state::VtState;
        use yserver_core::backend::Backend;

        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();

        assert_eq!(b.vt_state, VtState::Active);
        assert!(b.kms_outputs_active, "outputs start on");

        // Switch away: master is dropped, scanout gate closes.
        b.inject_seat_event_for_test(&mut state, false);
        assert_eq!(b.vt_state, VtState::Suspended);
        assert!(!b.scanout_allowed());

        // A blank arriving now must be a no-op, not a modeset attempt.
        b.set_dpms_power(3).expect("suspended DPMS must not error");
        assert!(
            b.kms_outputs_active,
            "cached output state must not flip while suspended — the commit \
             cannot have run, so claiming the outputs are off would desync \
             the cache from the hardware"
        );

        // The synthetic DRM fd cannot be probed on resume. Do not reopen the
        // scanout gate merely because shutdown was requested asynchronously.
        b.inject_seat_event_for_test(&mut state, true);
        assert_eq!(b.vt_state, VtState::Resuming);
        assert!(
            !b.scanout_allowed(),
            "failed resume must keep the gate closed"
        );
    }

    /// After `inject_seat_event_for_test(false)` the backend must be in
    /// `Suspended` and `scanout_allowed()` must return `false`.
    ///
    /// Also verifies that pre-seeded held keys and buttons are cleared by
    /// `synthesize_held_releases` inside `run_suspend`.
    #[test]
    fn vt_switch_disable_transitions_to_suspended_and_releases_held_input() {
        use crate::vt::state::VtState;

        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();

        // Pre-seed held keys and a button so we can verify they're cleared.
        b.core.down_keys.insert(38); // 'a'
        b.core.down_keys.insert(56); // 'b'
        b.core.button_mask = 0x0100; // BTN_LEFT held

        // Precondition: starts Active with scanout allowed.
        assert_eq!(b.vt_state, VtState::Active);
        assert!(
            b.scanout_allowed(),
            "scanout must be allowed before disable"
        );

        // Drive the Disable event.
        b.inject_seat_event_for_test(&mut state, false);

        // (a) State machine reached Suspended.
        assert_eq!(
            b.vt_state,
            VtState::Suspended,
            "vt_state must be Suspended after Disable"
        );

        // (b) Scanout gate is closed.
        assert!(
            !b.scanout_allowed(),
            "scanout must not be allowed while Suspended"
        );

        // (c) Held keys cleared by synthesize_held_releases.
        assert!(
            b.core.down_keys.is_empty(),
            "down_keys must be empty after suspend (synthesize_held_releases)"
        );

        // (d) Held buttons cleared.
        assert_eq!(
            b.core.button_mask, 0,
            "button_mask must be 0 after suspend (synthesize_held_releases)"
        );
    }

    /// After a Disable→Enable cycle the state machine must return to `Active`.
    ///
    /// The test uses a zero-device configuration, for which an empty connector
    /// snapshot and an empty re-light are both successful by design.
    #[test]
    fn vt_switch_enable_after_disable_returns_to_active() {
        use crate::vt::state::VtState;

        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        make_vt_fixture_headless(&mut b);

        // Drive Disable → Suspended.
        b.inject_seat_event_for_test(&mut state, false);
        assert_eq!(b.vt_state, VtState::Suspended);

        // Drive Enable → Active through the valid headless resume path.
        b.inject_seat_event_for_test(&mut state, true);

        assert_eq!(
            b.vt_state,
            VtState::Active,
            "vt_state must be Active after Enable completes"
        );
        assert!(
            b.scanout_allowed(),
            "scanout must be allowed after returning to Active"
        );
    }

    /// A rapid Disable-then-Enable-then-Disable sequence exercises the
    /// no-blink boundary: a `Disable` coalesced during a resume sequence
    /// causes `resume_complete` to return `BeginSuspend`, skipping `Active`
    /// entirely.  The final state must be `Suspended`, not `Active`.
    ///
    /// Concretely this test drives:
    ///
    ///  1. Disable → Suspending → (suspend sequence) → Suspended
    ///  2. Enable  → Resuming → (resume sequence) → resume_complete;
    ///     before step 2 we pre-seed `pending_disable = true` to simulate
    ///     a Disable that arrived mid-resume.
    ///  3. `resume_complete` sees `pending_disable` → returns `BeginSuspend`
    ///     → run_suspend again → Suspended
    ///
    /// The final assertion is `Suspended` and no panic (RefCell re-entrancy
    /// is exercised by the full Disable→Enable path above as well).
    #[test]
    fn vt_switch_rapid_double_switch_never_passes_through_active() {
        use crate::vt::state::{VtPending, VtState};

        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        make_vt_fixture_headless(&mut b);

        // Step 1: normal Disable → Suspended.
        b.inject_seat_event_for_test(&mut state, false);
        assert_eq!(b.vt_state, VtState::Suspended);

        // Simulate a Disable that arrives during the resume sequence by
        // pre-seeding `pending_disable`.  In production this would be set
        // by `on_event(Disable)` arriving while `vt_state == Resuming`
        // (the coalesce arm in `VtState::on_event`).  We set it directly
        // here because the stub drives events synchronously and we cannot
        // interleave them mid-sequence without modifying the backend.
        b.vt_pending = VtPending {
            pending_disable: true,
            pending_enable: false,
        };

        // Step 2: Enable with pending_disable set → resume_complete skips
        // Active and goes straight to Suspending → run_suspend → Suspended.
        b.inject_seat_event_for_test(&mut state, true);

        assert_eq!(
            b.vt_state,
            VtState::Suspended,
            "rapid double-switch must end in Suspended, never passing through Active"
        );
        assert!(
            !b.scanout_allowed(),
            "scanout must not be allowed after rapid double-switch lands in Suspended"
        );
        // pending_disable must have been consumed by resume_complete.
        assert!(
            !b.vt_pending.pending_disable,
            "pending_disable must be cleared after resume_complete consumed it"
        );
    }

    /// A coalesced `pending_enable` (an Enable that arrived during the
    /// suspend sequence) must be consumed by the drive loop and resume the
    /// session, not strand it in `Suspended`. Regression test for the
    /// final-review finding that `pending_enable` was set but never acted
    /// on. We pre-seed `pending_enable` (the synchronous stub can't
    /// interleave a real Enable mid-suspend) and drive a Disable; the loop
    /// must run suspend, then consume the flag and resume to `Active`.
    #[test]
    fn vt_switch_coalesced_enable_resumes_not_stranded_in_suspended() {
        use crate::vt::state::{VtPending, VtState};

        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        make_vt_fixture_headless(&mut b);

        b.vt_pending = VtPending {
            pending_enable: true,
            pending_disable: false,
        };

        b.inject_seat_event_for_test(&mut state, false);

        assert_eq!(
            b.vt_state,
            VtState::Active,
            "a coalesced pending_enable must drive a resume after suspend, not strand in Suspended"
        );
        assert!(
            !b.vt_pending.pending_enable,
            "pending_enable must be cleared once the consume-loop acts on it"
        );
    }

    /// Re-entrancy smoke: a full Disable→Enable cycle completes without a
    /// `RefCell` borrow panic. In the stub harness this verifies that no
    /// backend `RefCell` panics during the sequence.
    #[test]
    fn vt_switch_full_cycle_no_refcell_panic() {
        use crate::vt::state::VtState;

        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        make_vt_fixture_headless(&mut b);

        // Two full cycles — if any RefCell is double-borrowed this panics.
        for _ in 0..2 {
            b.inject_seat_event_for_test(&mut state, false);
            assert_eq!(b.vt_state, VtState::Suspended);
            b.inject_seat_event_for_test(&mut state, true);
            assert_eq!(b.vt_state, VtState::Active);
        }
    }

    // ────────────────────────────────────────────────────────────────
    // COW structural redesign — Phase 2 Task 2.2: get/release_overlay_window
    // own the FULL backend lifecycle (storage + windows +
    // top_level_order). The bool return signals the 0→1 / 1→0
    // transition so the core handler drives the symmetric resources-
    // side materialization once per lifecycle event.
    // ────────────────────────────────────────────────────────────────

    #[test]
    fn get_overlay_window_first_claim_materializes_full_backend_state() {
        let mut b = KmsBackend::for_tests();
        let fb_w = u32::from(b.platform.fb_w);
        let fb_h = u32::from(b.platform.fb_h);

        let was_first_claim = b.get_overlay_window(None).expect("get_overlay_window");
        assert!(was_first_claim, "0→1 transition must return Ok(true)");

        let cow_host_xid = b
            .cow_host_xid()
            .expect("cow_host_xid getter must return Some after first claim");
        let geom = b
            .windows
            .get(&cow_host_xid)
            .expect("COW must be present in windows after first claim");
        assert!(geom.mapped);
        assert_eq!(geom.depth, 24);
        assert_eq!(u32::from(geom.width), fb_w);
        assert_eq!(u32::from(geom.height), fb_h);
        assert_eq!(geom.parent, None);
        // Step 2 (DRIFT 2): get_overlay_window no longer pushes the COW into
        // top_level_order — that membership is projected from core children
        // by the GetOverlayWindow core handler (after materialize_cow_resource)
        // via sync_top_level_order. Covered end-to-end by the
        // `drift2_raise_keeps_cow_on_top` projection gate.
    }

    #[test]
    fn get_overlay_window_second_claim_does_not_remateralize() {
        let mut b = KmsBackend::for_tests();
        b.get_overlay_window(None).expect("first claim");
        let cow_host_xid = b.cow_host_xid().expect("after first claim");
        // Snapshot the rank to make sure a second claim doesn't reallocate.
        let rank_before = b.windows.get(&cow_host_xid).unwrap().stack_rank;

        let was_first_claim = b.get_overlay_window(None).expect("second claim");
        assert!(!was_first_claim, "subsequent claim must return Ok(false)");
        let rank_after = b.windows.get(&cow_host_xid).unwrap().stack_rank;
        assert_eq!(
            rank_before, rank_after,
            "subsequent claim must not rebuild windows entry"
        );
    }

    #[test]
    fn release_overlay_window_final_release_tears_down_full_backend_state() {
        let mut b = KmsBackend::for_tests();
        b.get_overlay_window(None).expect("get");
        let cow_host_xid = b.cow_host_xid().expect("present");

        let was_final_release = b.release_overlay_window(None).expect("release");
        assert!(was_final_release, "1→0 transition must return Ok(true)");
        assert!(
            !b.windows.contains_key(&cow_host_xid),
            "COW removed from windows on final release"
        );
        assert!(
            !b.core.top_level_order.contains(&cow_host_xid),
            "COW removed from top_level_order"
        );
        assert!(
            b.cow_host_xid().is_none(),
            "cow_host_xid getter returns None after final release"
        );
    }

    /// `set_logical_screen_size` updates `fb_w`/`fb_h`, reallocates root
    /// storage to the new dimensions, and leaves the scene dirty without
    /// calling `drain_all` or `rebuild_outputs` (which would clear
    /// `pending_acks` and expose a kernel-level EBUSY if a flip was in
    /// flight).  On the no-Vk test fixture, the root storage is a null-view
    /// stub; the test verifies the observable contract:
    ///
    /// - `platform.fb_w` / `fb_h` carry the new size.
    /// - Root xid is still live in the store with the new extent.
    /// - The scene is marked dirty (next tick will repaint).
    /// - A second call to the same dimensions is idempotent.
    #[test]
    fn set_logical_screen_size_updates_fb_and_root_storage() {
        use yserver_core::backend::Backend;

        let mut b = KmsBackend::for_tests();
        let initial_w = b.platform.fb_w;
        let initial_h = b.platform.fb_h;
        let initial_epoch = b.crtc_config_topology_epoch;

        // Sanity: root storage allocated at boot dimensions.
        let root_xid = b.core.window_id;
        let id_before = b
            .store
            .lookup(root_xid)
            .expect("root must be live before resize");
        let extent_before = b.store.get(id_before).unwrap().storage.extent;
        assert_eq!(extent_before.width, u32::from(initial_w));
        assert_eq!(extent_before.height, u32::from(initial_h));

        // Perform resize.
        let new_w: u16 = initial_w.saturating_add(1280);
        let new_h: u16 = initial_h.saturating_add(0); // height unchanged
        b.set_logical_screen_size(new_w, new_h)
            .expect("set_logical_screen_size must not fail on test fixture");

        // Platform extent updated.
        assert_eq!(b.platform.fb_w, new_w, "fb_w must reflect new width");
        assert_eq!(b.platform.fb_h, new_h, "fb_h must reflect new height");
        assert_eq!(
            b.crtc_config_topology_epoch,
            initial_epoch.wrapping_add(1),
            "a changed logical extent invalidates pending topology snapshots",
        );

        // Root xid is live with the new extent.
        let id_after = b
            .store
            .lookup(root_xid)
            .expect("root must still be live after resize");
        let extent_after = b.store.get(id_after).unwrap().storage.extent;
        assert_eq!(
            extent_after.width,
            u32::from(new_w),
            "root extent.width must match new_w"
        );
        assert_eq!(
            extent_after.height,
            u32::from(new_h),
            "root extent.height must match new_h"
        );

        // DrawableId changes (new allocation) — old storage freed/parked.
        assert_ne!(
            id_before, id_after,
            "resize must produce a fresh DrawableId for root"
        );

        // Scene is dirty — next tick will compose with new dimensions.
        assert!(
            b.scene.scene_structure_dirty,
            "scene must be marked dirty after resize so next tick repaints"
        );

        // Idempotent: same dimensions again must succeed without panic.
        b.set_logical_screen_size(new_w, new_h)
            .expect("repeat call to same dimensions must succeed");
        assert_eq!(b.platform.fb_w, new_w);
        assert_eq!(b.platform.fb_h, new_h);
        assert_eq!(
            b.crtc_config_topology_epoch,
            initial_epoch.wrapping_add(1),
            "an idempotent logical-size request must not invalidate probes",
        );
    }

    /// Frame tick: advances mod n, re-arms relative, mints strictly
    /// increasing versions across a full wraparound (XFixes serial
    /// contract — naive Arc-swapping would repeat v1,v2,v1).
    #[test]
    fn anim_tick_advances_wraps_and_stays_monotonic() {
        use std::time::{Duration, Instant};
        use yserver_core::backend::{Backend, CursorHandle};

        let mut b = KmsBackend::for_tests();
        // Insert records directly with DISTINCT bytes per frame —
        // `create_cursor` on an unreadable test pixmap degenerates to
        // identical 1×1 transparent bytes, making the bytes assert
        // below vacuous.
        let c1_xid = b.core.next_host_xid();
        b.insert_cursor_record(c1_xid, 1, 1, 0, 0, vec![0xAA, 0x00, 0x00, 0xFF]);
        let c1 = CursorHandle::from_raw(c1_xid).unwrap();
        let c2_xid = b.core.next_host_xid();
        b.insert_cursor_record(c2_xid, 1, 1, 0, 0, vec![0x00, 0xBB, 0x00, 0xFF]);
        let c2 = CursorHandle::from_raw(c2_xid).unwrap();
        let anim = b
            .create_anim_cursor(None, &[(c1, 50), (c2, 75)])
            .expect("anim")
            .expect("KMS animates");
        let root_host = b.core.window_id;
        b.define_cursor(None, root_host, anim.as_raw())
            .expect("define");

        let mut last_version = b.cursor_records.get(&anim.as_raw()).unwrap().version;
        let mut expected_frame = 0usize;
        // 5 ticks over 2 frames = two full wraparounds.
        for i in 0..5 {
            // Force the deadline into the past, then tick.
            b.active_cursor_anim.as_mut().unwrap().next_frame =
                Instant::now() - Duration::from_millis(1);
            b.tick_cursor_animation();
            expected_frame = (expected_frame + 1) % 2;
            let st = b.active_cursor_anim.as_ref().expect("still armed");
            assert_eq!(st.frame, expected_frame, "tick {i}");
            assert!(st.next_frame > Instant::now() - Duration::from_millis(1));
            let v = b.cursor_records.get(&anim.as_raw()).unwrap().version;
            assert!(v > last_version, "tick {i}: version {v} !> {last_version}");
            last_version = v;
            // The canonical record now carries the frame's bytes.
            let frame_rec =
                &b.anim_cursor_records.get(&anim.as_raw()).unwrap().frames[expected_frame].record;
            assert_eq!(
                b.cursor_records.get(&anim.as_raw()).unwrap().bgra_bytes,
                frame_rec.bgra_bytes,
            );
        }
        // Tick before the deadline → no advance.
        let frame_before = b.active_cursor_anim.as_ref().unwrap().frame;
        b.tick_cursor_animation();
        assert_eq!(b.active_cursor_anim.as_ref().unwrap().frame, frame_before);
    }

    /// next_wakeup reports the anim deadline only while outputs are
    /// active and scanout is allowed (EINVAL-storm discipline).
    #[test]
    fn anim_deadline_gated_on_outputs_active() {
        use crate::vt::state::VtState;
        use std::time::{Duration, Instant};
        use yserver_core::backend::{Backend, PixmapHandle};

        let mut b = KmsBackend::for_tests();
        let pix = PixmapHandle::from_raw(0x1234_0060).unwrap();
        let c1 = b
            .create_cursor(None, pix, None, (0xFFFF, 0, 0), (0, 0, 0), 0, 0)
            .expect("c1");
        let anim = b
            .create_anim_cursor(None, &[(c1, 50)])
            .expect("anim")
            .expect("KMS animates");
        let root_host = b.core.window_id;
        b.define_cursor(None, root_host, anim.as_raw())
            .expect("define");
        let deadline = b.active_cursor_anim.as_ref().unwrap().next_frame;

        let wake = b.next_wakeup().expect("deadline reported");
        assert!(wake <= deadline);

        // DPMS off → deadline not reported, tick is a no-op.
        b.kms_outputs_active = false;
        let frame = b.active_cursor_anim.as_ref().unwrap().frame;
        b.active_cursor_anim.as_mut().unwrap().next_frame =
            Instant::now() - Duration::from_millis(1);
        assert!(
            b.next_wakeup().is_none_or(|w| w > Instant::now()),
            "stale anim deadline must not be reported while outputs are off",
        );
        b.tick_cursor_animation();
        assert_eq!(
            b.active_cursor_anim.as_ref().unwrap().frame,
            frame,
            "tick must not advance while outputs are off",
        );

        // Outputs back on with the deadline in the past → exactly one
        // immediate advance (spec: no fast-forward through missed frames).
        b.kms_outputs_active = true;
        b.tick_cursor_animation();
        assert_eq!(
            b.active_cursor_anim.as_ref().unwrap().frame,
            frame,
            "1-frame anim wraps to same index"
        );
        assert!(
            b.active_cursor_anim.as_ref().unwrap().next_frame > Instant::now(),
            "re-armed from now: next_frame must be a future instant after DPMS restore tick",
        );

        // VT-away / master-drop uses the same scheduler suppression.
        b.vt_state = VtState::Suspended;
        b.active_cursor_anim.as_mut().unwrap().next_frame =
            Instant::now() - Duration::from_millis(1);
        assert!(
            b.next_wakeup().is_none_or(|w| w > Instant::now()),
            "stale anim deadline must not be reported while scanout is disallowed",
        );
        b.tick_cursor_animation();
        assert_eq!(
            b.active_cursor_anim.as_ref().unwrap().frame,
            frame,
            "tick must not advance while scanout is disallowed",
        );
    }

    // ── depth-1 GXcopy GPU fast-path tests (Task 4, 2026-06-21) ──

    /// depth-1 + GXcopy + full plane-mask MUST NOT increment
    /// `cpufill_depth_lt8` or `cpufill_depth1_gxcopy`: the new fast-path
    /// intercepts before the CPU-fallback gate. The stub engine returns
    /// NoVk (no Vulkan in this fixture), so no paint_submit happens, but
    /// the routing observable — the CPU-fallback counters stay zero — is
    /// the load-bearing signal.
    #[test]
    fn depth1_gxcopy_fill_routes_to_gpu_not_cpu_readback() {
        use crate::kms::render::store::DrawableKind;
        use ash::vk;
        use yserver_core::backend::GcFunction;

        let mut b = KmsBackend::for_tests();
        let xid: u32 = 0xD100_0001;
        let storage = Storage::for_tests_null(
            vk::Extent2D {
                width: 4,
                height: 4,
            },
            vk::Format::R8_UNORM,
        );
        b.store
            .allocate(xid, DrawableKind::Pixmap, 1, false, storage)
            .expect("allocate depth-1");

        // Default state: GcFunction::Copy, current_plane_mask=u32::MAX → full
        assert!(matches!(b.core.current_function, GcFunction::Copy));

        let before_cpufill = b.telemetry.lifetime.cpufill_depth_lt8;
        let before_d1gxcopy = b.telemetry.lifetime.cpufill_depth1_gxcopy;

        b.fill_rectangle(None, xid, 1, 0, 0, 4, 4)
            .expect("fill_rectangle");

        assert_eq!(
            b.telemetry.lifetime.cpufill_depth_lt8, before_cpufill,
            "depth-1 GXcopy must NOT hit the CPU fallback (cpufill_depth_lt8)"
        );
        assert_eq!(
            b.telemetry.lifetime.cpufill_depth1_gxcopy, before_d1gxcopy,
            "depth-1 GXcopy must NOT hit the CPU fallback (cpufill_depth1_gxcopy)"
        );
    }

    /// depth-1 + non-Copy function (GXxor) MUST still use the CPU fallback
    /// (boolean logic hazard in R8 byte-wise ops — the GPU path is only
    /// valid for GXcopy). Asserts `cpufill_depth_lt8` increments by 1.
    #[test]
    fn depth1_noncopy_fill_still_cpu_fallback() {
        use crate::kms::render::store::DrawableKind;
        use ash::vk;
        use yserver_core::backend::GcFunction;

        let mut b = KmsBackend::for_tests();
        let xid: u32 = 0xD100_0002;
        let storage = Storage::for_tests_null(
            vk::Extent2D {
                width: 4,
                height: 4,
            },
            vk::Format::R8_UNORM,
        );
        b.store
            .allocate(xid, DrawableKind::Pixmap, 1, false, storage)
            .expect("allocate depth-1");

        b.core.current_function = GcFunction::Xor;

        let before = b.telemetry.lifetime.cpufill_depth_lt8;
        b.fill_rectangle(None, xid, 1, 0, 0, 4, 4)
            .expect("fill_rectangle");
        assert_eq!(
            b.telemetry.lifetime.cpufill_depth_lt8,
            before + 1,
            "depth-1 non-Copy must fall back to CPU path"
        );
    }

    /// depth-4 + GXcopy MUST still use the CPU fallback (no equivalence
    /// proof for R8 depth-4 fills). Asserts `cpufill_depth_lt8` increments.
    #[test]
    fn depth4_fill_still_cpu_fallback() {
        use crate::kms::render::store::DrawableKind;
        use ash::vk;
        use yserver_core::backend::GcFunction;

        let mut b = KmsBackend::for_tests();
        let xid: u32 = 0xD400_0001;
        let storage = Storage::for_tests_null(
            vk::Extent2D {
                width: 4,
                height: 4,
            },
            vk::Format::R8_UNORM,
        );
        b.store
            .allocate(xid, DrawableKind::Pixmap, 4, false, storage)
            .expect("allocate depth-4");

        // Default: GcFunction::Copy
        assert!(matches!(b.core.current_function, GcFunction::Copy));

        let before = b.telemetry.lifetime.cpufill_depth_lt8;
        b.fill_rectangle(None, xid, 0x0F, 0, 0, 4, 4)
            .expect("fill_rectangle");
        assert_eq!(
            b.telemetry.lifetime.cpufill_depth_lt8,
            before + 1,
            "depth-4 GXcopy must still fall back to CPU path"
        );
    }

    /// End-to-end: writing a depth-1 pixmap via the GPU fast-path MUST
    /// bump the drawable's `content_version`, so a stale clip-mask cache
    /// entry (built before the fill) is invalidated. Requires a live
    /// Vulkan ICD (lavapipe) to actually commit the logic_fill.
    #[test]
    #[ignore = "needs live Vulkan ICD (lavapipe)"]
    fn clip_cache_invalidated_on_mask_depth1_gpu_fill() {
        use yserver_core::backend::GcFunction;

        let mut b = match KmsBackend::for_tests_with_vk() {
            Ok(b) => b,
            Err(e) => {
                eprintln!("skipping: no Vk: {e}");
                return;
            }
        };

        // Allocate a depth-1 pixmap via the Backend trait (real Vk storage).
        let pix = b
            .create_pixmap(None, 1, 4, 4)
            .expect("create_pixmap depth-1");
        let xid = pix.as_raw();

        // Resolve the DrawableId for the xid.
        let did = b.store.lookup(xid).expect("drawable in store");

        // Snapshot the content_version before the fill.
        let version_before = b.store.get(did).expect("drawable").content_version;

        // Seed a clip-mask cache pretending this pixmap was read at
        // `version_before` — simulates having read it before the fill.
        b.clip_mask_cache = Some(crate::kms::backend::ClipMaskCache {
            pixmap_xid: xid,
            drawable_id: did,
            content_version: version_before,
            origin: (0, 0),
            width: 4,
            height: 4,
            depth: 1,
            row_stride: 4,
            cpu_bytes_pending: false,
            bytes: vec![0x00, 0, 0, 0, 0x00, 0, 0, 0, 0x00, 0, 0, 0, 0x00, 0, 0, 0],
        });
        assert!(
            b.clip_cache_reusable(xid),
            "cache must be reusable before the fill"
        );

        // Fill via the GPU fast-path (depth-1, GXcopy, full plane-mask).
        assert!(matches!(b.core.current_function, GcFunction::Copy));
        b.fill_rectangle(None, xid, 1, 0, 0, 4, 4)
            .expect("fill_rectangle depth-1");

        // The GPU fill MUST have bumped content_version.
        let version_after = b.store.get(did).expect("drawable").content_version;
        assert!(
            version_after > version_before,
            "GPU fill must bump content_version (before={version_before}, after={version_after})"
        );

        // Consequently the clip-mask cache is now stale.
        assert!(
            !b.clip_cache_reusable(xid),
            "clip-mask cache must be invalid after GPU fill bumped content_version"
        );
    }

    /// XFixes GetCursorImage tracks the animation: bytes follow the
    /// current frame, serial strictly increases across a wraparound.
    #[test]
    fn xfixes_cursor_image_follows_animation_frames() {
        use std::time::{Duration, Instant};
        use yserver_core::backend::{Backend, CursorHandle};

        let mut b = KmsBackend::for_tests();
        // Insert records directly with DISTINCT bytes per frame —
        // `create_cursor` on an unreadable test pixmap degenerates to
        // identical 1×1 transparent bytes, making the bytes assert
        // below vacuous.
        let c1_xid = b.core.next_host_xid();
        b.insert_cursor_record(c1_xid, 1, 1, 0, 0, vec![0xAA, 0x00, 0x00, 0xFF]);
        let c1 = CursorHandle::from_raw(c1_xid).unwrap();
        let c2_xid = b.core.next_host_xid();
        b.insert_cursor_record(c2_xid, 1, 1, 0, 0, vec![0x00, 0xBB, 0x00, 0xFF]);
        let c2 = CursorHandle::from_raw(c2_xid).unwrap();
        let anim = b
            .create_anim_cursor(None, &[(c1, 50), (c2, 75)])
            .expect("anim")
            .expect("KMS animates");
        let root_host = b.core.window_id;
        b.define_cursor(None, root_host, anim.as_raw())
            .expect("define");

        let mut last_serial = b.get_active_cursor_image().expect("image").serial;
        for _ in 0..4 {
            b.active_cursor_anim.as_mut().unwrap().next_frame =
                Instant::now() - Duration::from_millis(1);
            b.tick_cursor_animation();
            let img = b.get_active_cursor_image().expect("image");
            assert!(img.serial > last_serial, "serial must strictly increase");
            last_serial = img.serial;
            let frame_idx = b.active_cursor_anim.as_ref().unwrap().frame;
            let frame_rec =
                &b.anim_cursor_records.get(&anim.as_raw()).unwrap().frames[frame_idx].record;
            assert_eq!(*img.bgra_bytes, frame_rec.bgra_bytes);
        }
    }

    #[test]
    fn load_keymap_by_components_multigroup() {
        use yserver_core::backend::{Backend, KeymapLoad};

        let mut backend = KmsBackend::for_tests();
        // The German switch string from the capture.
        let r = backend.load_keymap_by_components("pc+us+de:2+us:3+inet(evdev)");
        match r {
            KeymapLoad::Loaded { changed, .. } => assert!(changed, "first load is a change"),
            KeymapLoad::Failed => panic!("should load"),
        }
        // keycode 29 group 1 is now German `z`
        assert_eq!(
            backend
                .core
                .xkb_keymap
                .0
                .key_get_syms_by_level(xkbcommon::xkb::Keycode::new(29), 1, 0)
                .first()
                .map(|s| s.raw()),
            Some(0x7a)
        );
        // A second identical load is still Loaded, but changed=false.
        let r2 = backend.load_keymap_by_components("pc+us+de:2+us:3+inet(evdev)");
        assert!(matches!(r2, KeymapLoad::Loaded { changed: false, .. }));
        // An unparseable symbols string fails closed -> keymap unchanged.
        let r3 = backend.load_keymap_by_components("pc+wat_xyz_unknown:2+inet(evdev)");
        assert_eq!(r3, KeymapLoad::Failed);
    }

    #[test]
    fn load_keymap_by_components_preserves_level3_chooser_option() {
        use xkbcommon::xkb::{KeyDirection, Keycode};
        use yserver_core::backend::{Backend, KeymapLoad};

        let mut backend = KmsBackend::for_tests();
        let r = backend.load_keymap_by_components(
            "pc+us+be:2+us:3+inet(evdev)+capslock(none)+level3(ralt_switch)",
        );
        assert!(matches!(r, KeymapLoad::Loaded { .. }), "loads, got {r:?}");

        // LOAD-BEARING, machine-independent guard: the `level3(ralt_switch)`
        // chooser partial from the symbols string must survive into the
        // recompiled keymap's RMLVO options as `lv3:ralt_switch` (was dropped
        // before the fix → `options: None`). This is what makes AltGr bind to
        // Mod5 on systems whose xkb-data does NOT default the chooser (the
        // real-HW failure on `silence`). NB: the downstream €-resolution itself
        // is xkb-DATA-dependent — on a machine whose `pc105` default already
        // binds RAlt→Mod5 it resolves with or without the option, so asserting
        // € here would be vacuous; we assert the option survived instead.
        let opts = backend.core.xkb_rmlvo.options.as_deref().unwrap_or("");
        assert!(
            opts.split(',').any(|o| o == "lv3:ralt_switch"),
            "lv3:ralt_switch must be preserved into rmlvo.options, got {opts:?}"
        );
        assert!(
            opts.split(',').any(|o| o == "caps:none"),
            "caps:none must be preserved too, got {opts:?}"
        );

        // Best-effort downstream check (informational; may pass regardless of
        // the option on xkb-data that defaults the chooser): on the `be` group,
        // RAlt+e should reach EuroSign.
        let st = &mut backend.core.xkb_state.0;
        st.update_mask(0, 0, 0, 0, 0, 1); // lock layout 1 (be)
        st.update_key(Keycode::new(108), KeyDirection::Down); // RAlt
        assert_eq!(
            st.key_get_one_sym(Keycode::new(26)).raw(),
            0x20ac,
            "AltGr+e on the be group resolves to EuroSign"
        );
    }

    #[test]
    fn xkb_get_kbd_by_name_parses_capture_loads_and_notifies() {
        use yserver_core::backend::Backend;

        // Reconstruct the EXACT GetKbdByName request body from
        // cinnamon-xorg.xtrace:6201 (after the 4-byte XKB request header the
        // core loop strips): deviceSpec(2) need(2) want(2) load(1) pad(1),
        // then CARD8-length-prefixed component strings in the order
        // keymap, keycodes, types, compat, symbols, geometry.
        let mut body: Vec<u8> = Vec::new();
        body.extend_from_slice(&0x0100u16.to_le_bytes()); // deviceSpec
        body.extend_from_slice(&0x00bfu16.to_le_bytes()); // need
        body.extend_from_slice(&0x00ffu16.to_le_bytes()); // want
        body.push(1); // load = TRUE
        body.push(0); // pad
        for s in [
            "",                            // keymap (empty)
            "evdev+aliases(qwerty)",       // keycodes
            "complete",                    // types
            "complete",                    // compat
            "pc+us+de:2+us:3+inet(evdev)", // symbols
            "pc(pc105)",                   // geometry
        ] {
            body.push(u8::try_from(s.len()).unwrap());
            body.extend_from_slice(s.as_bytes());
        }

        let mut backend = KmsBackend::for_tests();
        let mut next_atom = 1u32;
        let (reply, notify) = backend
            .xkb_get_kbd_by_name(&body, &mut |_name| {
                let a = next_atom;
                next_atom += 1;
                a
            })
            .expect("real backend builds a GetKbdByName reply");

        // Header: loaded BOOL, found/reported MASKS (captured 0x7f / 0xff).
        assert_eq!(reply[10], 1, "loaded = TRUE");
        assert_eq!(
            u16::from_le_bytes([reply[12], reply[13]]),
            0x007f,
            "found mask matches capture"
        );
        assert_eq!(
            u16::from_le_bytes([reply[14], reply[15]]),
            0x00ff,
            "reported mask matches capture"
        );
        // The symbols component actually loaded the German group: keycode 29
        // group 1 level 0 is `z` (0x7a) under us+de.
        assert_eq!(
            backend
                .core
                .xkb_keymap
                .0
                .key_get_syms_by_level(xkbcommon::xkb::Keycode::new(29), 1, 0)
                .first()
                .map(|s| s.raw()),
            Some(0x7a),
            "symbols component loaded the de group"
        );
        // First load is a change -> NewKeyboardNotify with changed=0x0003.
        let info = notify.expect("a changing load broadcasts NewKeyboardNotify");
        assert_eq!(info.changed, 0x0003, "changed = Keycodes|Geometry");
        assert!(
            info.min_keycode <= info.max_keycode,
            "new keycode range is sane"
        );

        // A second identical request still succeeds (loaded=1) but does NOT
        // broadcast (changed=false -> no NKN churn).
        let (reply2, notify2) = backend
            .xkb_get_kbd_by_name(&body, &mut |_| 1u32)
            .expect("reply on reload");
        assert_eq!(reply2[10], 1, "reload still loaded = TRUE");
        assert!(
            notify2.is_none(),
            "unchanged reload must not broadcast NewKeyboardNotify"
        );
    }

